# =============================================================================
# RUN ALL — rebuild the Llama-8B steering direction and re-run Llama-8B steering
#
# Runs four steps one after another, with no input needed. Use a GPU runtime
# (step 2 needs it). Every step is skipped or resumes if it already finished,
# so if the runtime dies, just run this file again.
#
#   1. direction  11_reextract_llama8b.py, STAGES = ["direction"]   (CPU work)
#                 -> steering_directions_llama8b_reextract.json
#                 skipped if that file already exists
#   2. steering   09_necessity_rerun.py, STAGE = "steering",
#                 LLAMA_DIRECTION = "reextract", SAMPLE = "original"   (GPU, ~4.5 h)
#                 Llama-8B only, seeds 4000 + r, multiplier 1.5; resumes per event
#   3. analyze    09_necessity_rerun.py, STAGE = "analyze"            (CPU, minutes)
#   4. report     steering_efficacy_rerun.py, STAGE = "report"        (CPU, minutes)
#
# The three scripts are embedded below exactly as shipped (pipeline/11,
# pipeline/09, analyses/steering_efficacy_rerun.py); only their settings lines
# are set per step. If a step fails, the later steps are not run.
#
# Everything printed is also saved to
#   hand_labeling_export/RUN_llama8b_direction_log.txt
# so you can read the results there when you check back.
# =============================================================================
import io, os, re, sys, time, traceback, contextlib
from pathlib import Path

DATA_ROOT = Path(os.environ.get("REVISION_DATA_ROOT", "/content/gdrive/MyDrive/llm_planning_study"))
if not DATA_ROOT.exists():
    from google.colab import drive; drive.mount("/content/gdrive")
EXPORT = DATA_ROOT / "hand_labeling_export"
LOG = EXPORT / "RUN_llama8b_direction_log.txt"

class Tee(io.TextIOBase):
    """Prints to the cell and appends to the log file on Drive."""
    def __init__(self, stream): self.stream = stream
    def write(self, s):
        self.stream.write(s)
        try:
            with open(LOG, "a") as f: f.write(s)
        except OSError:
            pass
        return len(s)
    def flush(self): self.stream.flush()

SRC = {}
SRC['reextract'] = '# =============================================================================\n# 11 — RE-EXTRACT THE DeepSeek-R1-Distill-Llama-8B ACTIVATIONS\n#\n# WHY. For the three Qwen models, recomputing the extractor\'s window centre\n# from the traces, labels and tokenizer reproduces every stored token_idx.\n# For DeepSeek-R1-Distill-Llama-8B it reproduces 3 of 1,021 revision and 2 of\n# 505 filler windows, under every text / cleaning / prompt variant tested\n# (analyses/diagnose_llama8b_window_alignment.py). Row mapping is correct and\n# the traces and labels are older than the activation files; the cause is\n# unknown. So it is not known which token position the stored Llama-8B windows\n# represent. This re-runs extraction for Llama-8B with the current code.\n#\n# WHAT. Notebooks 03 (revision windows), 05 (filler windows) and 06 (Table 1\n# probe, Parts A and B), copied VERBATIM from pipeline/. The only changes are\n# marked "# CHANGED": the model (Llama-8B) and the output folders / result\n# files, which are NEW, so nothing existing is overwritten:\n#     activations_reextract_2026_11/DeepSeek-R1-Distill-Llama-8B/\n#     activations_filler_reextract_2026_11/DeepSeek-R1-Distill-Llama-8B/\n#     results_v3/task1_residual_cis_nboot2000_v3_llama8b_reextract.json\n#     results_v3/task1_residual_pointfix_llama8b_reextract.json\n#     hand_labeling_export/llama8b_reextract_verification.json\n#\n# STAGES (set STAGES below; run in this order, each resumes if interrupted):\n#   "revision"  GPU. Notebook 03. Skips problems already in its extraction log.\n#   "filler"    GPU. Notebook 05. Skips problems whose .npz already exists.\n#   "verify"    CPU. Checks the new windows (recomputed centre == stored, for\n#               every event), where they sit relative to the marker, and how\n#               they compare with the OLD windows (does the old centre vector\n#               appear anywhere in the new window?).\n#   "probe"     CPU, hours. Notebook 06 Part A then Part B on the new windows.\n#   "direction" CPU. Notebook 08 cell 1: the Llama-8B steering direction from\n#               the new windows (new file), compared with the published one.\n#               Then 09_necessity_rerun.py with LLAMA_DIRECTION = "reextract",\n#               STAGE = "steering", then "analyze".\n#   Then: analyses/probe_robustness_checks.py with ACTIVATIONS = "llama8b_reextract".\n#\n# DISK. Notebook 03 also stores control windows and norms; it prints its own\n# storage estimate before starting (Llama-8B: 32 layers x 61 tokens x 4096,\n# float16, per window, for revision AND control windows). Check Drive space.\n# =============================================================================\nSTAGES = ["revision", "filler"]          # then ["verify"], ["probe"], ["direction"]\n\nimport os, gc, json\nfrom pathlib import Path\nDATA_ROOT = Path(os.environ.get("REVISION_DATA_ROOT", "/content/gdrive/MyDrive/llm_planning_study"))\nif not DATA_ROOT.exists():\n    from google.colab import drive; drive.mount("/content/gdrive")\nprint("DATA_ROOT =", DATA_ROOT, " STAGES =", STAGES)\nNEW_REV = "activations_reextract_2026_11"\nNEW_FIL = "activations_filler_reextract_2026_11"\nLLAMA   = "DeepSeek-R1-Distill-Llama-8B"\nif "revision" in STAGES or "filler" in STAGES:\n    import torch\n\n\n# #############################################################################\n# STAGE "revision" — notebook 03, verbatim (Llama-8B, new output folder)\n# #############################################################################\nif "revision" in STAGES:\n    # ---- 03, cell 1 (verbatim except where marked) ----\n    # =============================================================================\n    # 03 — EXTRACT REVISION ACTIVATIONS\n    #\n    # PURPOSE: Re-run each model with forward hooks registered. For each labeled\n    #          revision token, extract ±30 token windows of residual stream\n    #          activations, attention patterns, and layer-wise norms.\n    #          Save compressed numpy arrays to Drive after every problem.\n    #\n    # INPUTS:  DATA_ROOT/traces/{model}/{problem_id}.json   (notebook 01)\n    #          DATA_ROOT/labels/{model}/{problem_id}.json   (notebook 02)\n    #\n    # OUTPUTS: DATA_ROOT/activations/{model}/\n    #              {problem_id}.npz           (compressed numpy arrays)\n    #              extraction_log.json        (progress tracker)\n    #          DATA_ROOT/activations_summary_all_models.json\n    #\n    # SPECIAL: Llama-3.1-8B-Instruct gets different handling —\n    #          500 random token windows instead of revision windows.\n    #          Set IS_BASELINE_MODEL = True for that run.\n    #\n    # RUNTIME: GPU required. One session per model.\n    #          Estimated: 3-5 hours per model on A100 80GB.\n    #\n    # RUN ORDER:\n    #   1. DeepSeek-R1-Distill-Llama-8B    IS_BASELINE_MODEL = False\n    #   2. Llama-3.1-8B-Instruct            IS_BASELINE_MODEL = True\n    #   3. DeepSeek-R1-Distill-Qwen-7B     IS_BASELINE_MODEL = False\n    #   4. DeepSeek-R1-Distill-Qwen-14B    IS_BASELINE_MODEL = False\n    #   5. DeepSeek-R1-Distill-Qwen-1.5B   IS_BASELINE_MODEL = False\n    # =============================================================================\n\n    # ---- 03, cell 3 (verbatim except where marked) ----\n    # -----------------------------------------------------------------------------\n    # CELL 2 — Imports and config\n    # -----------------------------------------------------------------------------\n    import gc\n    import json\n    import time\n    import random\n    import numpy as np\n    import torch\n    import torch.nn as nn\n    from pathlib import Path\n    from datetime import datetime\n    from collections import defaultdict\n    from transformers import AutoTokenizer, AutoModelForCausalLM, BitsAndBytesConfig\n\n    # ── MODEL SELECTION ───────────────────────────────────────────────────────────\n    #MODEL_NAME = "deepseek-ai/DeepSeek-R1-Distill-Llama-8B"\n    #MODEL_NAME = "meta-llama/Llama-3.1-8B-Instruct"\n    #MODEL_NAME = "deepseek-ai/DeepSeek-R1-Distill-Qwen-7B"\n    #MODEL_NAME = "deepseek-ai/DeepSeek-R1-Distill-Qwen-14B"\n    MODEL_NAME = "deepseek-ai/DeepSeek-R1-Distill-Llama-8B"   # CHANGED: Llama-8B\n    IS_BASELINE_MODEL = False   # True ONLY for Llama-3.1-8B-Instruct\n\n    # ── EXTRACTION CONFIG ─────────────────────────────────────────────────────────\n    WINDOW_TOKENS     = 30      # ±30 tokens around each revision\n    N_BASELINE_WINDOWS = 500    # random windows for Llama baseline\n    RANDOM_SEED        = 42\n\n    # ── QUANTIZATION ──────────────────────────────────────────────────────────────\n    USE_4BIT = "32B" in MODEL_NAME or "32b" in MODEL_NAME\n\n    # ── PATHS ─────────────────────────────────────────────────────────────────────\n    GDRIVE_BASE    = DATA_ROOT\n    MODEL_SHORT    = MODEL_NAME.split("/")[-1]\n    TRACE_DIR      = GDRIVE_BASE / "traces"  / MODEL_SHORT\n    LABEL_DIR      = GDRIVE_BASE / "labels"  / MODEL_SHORT\n    ACTIV_DIR      = GDRIVE_BASE / NEW_REV / MODEL_SHORT   # CHANGED: new folder\n    LOG_FILE       = ACTIV_DIR / "extraction_log.json"\n    SUMMARY_FILE   = GDRIVE_BASE / NEW_REV / "activations_summary_all_models.json"   # CHANGED\n\n    print(f"Model:        {MODEL_NAME}")\n    print(f"Baseline:     {IS_BASELINE_MODEL}")\n    print(f"Window:       ±{WINDOW_TOKENS} tokens")\n    print(f"Output dir:   {ACTIV_DIR}")\n\n    # ---- 03, cell 4 (verbatim except where marked) ----\n    # -----------------------------------------------------------------------------\n    # CELL 3 — Mount Google Drive\n    # -----------------------------------------------------------------------------\n    ACTIV_DIR.mkdir(parents=True, exist_ok=True)\n    print(f"Activation directory ready: {ACTIV_DIR}")\n\n    # ---- 03, cell 5 (verbatim except where marked) ----\n    # -----------------------------------------------------------------------------\n    # CELL 4 — Load model and tokenizer\n    # -----------------------------------------------------------------------------\n    def load_model_and_tokenizer(model_name: str, use_4bit: bool):\n        print(f"\\nLoading tokenizer...")\n        tokenizer = AutoTokenizer.from_pretrained(\n            model_name, trust_remote_code=True\n        )\n        if tokenizer.pad_token is None:\n            tokenizer.pad_token = tokenizer.eos_token\n\n        print(f"Loading model ({\'4-bit\' if use_4bit else \'fp16\'})...")\n        if use_4bit:\n            bnb_config = BitsAndBytesConfig(\n                load_in_4bit=True,\n                bnb_4bit_compute_dtype=torch.float16,\n                bnb_4bit_use_double_quant=True,\n                bnb_4bit_quant_type="nf4"\n            )\n            model = AutoModelForCausalLM.from_pretrained(\n                model_name,\n                quantization_config=bnb_config,\n                device_map="auto",\n                trust_remote_code=True\n            )\n        else:\n            model = AutoModelForCausalLM.from_pretrained(\n                model_name,\n                torch_dtype=torch.float16,\n                device_map="auto",\n                trust_remote_code=True\n            )\n\n        model.eval()\n\n        # Detect layer count and hidden dim automatically\n        config     = model.config\n        n_layers   = config.num_hidden_layers\n        hidden_dim = config.hidden_size\n        print(f"Model loaded. Layers: {n_layers}, Hidden dim: {hidden_dim}")\n        return model, tokenizer, n_layers, hidden_dim\n\n\n    model, tokenizer, N_LAYERS, HIDDEN_DIM = load_model_and_tokenizer(\n        MODEL_NAME, USE_4BIT\n    )\n\n    # ---- 03, cell 6 (verbatim except where marked) ----\n    # -----------------------------------------------------------------------------\n    # CELL 5 — Hook registration\n    # Hook into residual stream AFTER each transformer block.\n    # We capture output[0] which is the hidden state tensor.\n    # Hooks are registered once and stay active for all forward passes.\n    # -----------------------------------------------------------------------------\n    #------------------------------------------------------------------------\n    class ActivationStore:\n        """\n        Thread-safe store for activations captured by forward hooks.\n        Cleared before each forward pass via .clear().\n        """\n        def __init__(self):\n            self.data = {}\n\n        def clear(self):\n            self.data.clear()\n\n        def __setitem__(self, key, value):\n            self.data[key] = value\n\n        def __getitem__(self, key):\n            return self.data[key]\n\n        def keys(self):\n            return self.data.keys()\n\n    store = ActivationStore()\n\n\n    hooks = []\n\n    def register_hooks(model, store):\n        if hasattr(model, "model") and hasattr(model.model, "layers"):\n            layers = model.model.layers\n        elif hasattr(model, "transformer") and hasattr(model.transformer, "h"):\n            layers = model.transformer.h\n        else:\n            raise RuntimeError(f"Cannot find layers in {type(model)}")\n\n        hooks = []\n        for i, layer in enumerate(layers):\n            def make_hook(layer_idx):\n                def hook(module, input, output):\n                    hidden_state = output[0]\n                    if hidden_state.dim() == 3:\n                        store[layer_idx] = hidden_state[0].detach().cpu().float()\n                    elif hidden_state.dim() == 2:\n                        store[layer_idx] = hidden_state.detach().cpu().float()\n                    else:\n                        print(f"WARNING layer {layer_idx}: unexpected shape {hidden_state.shape}")\n                return hook\n            h = layer.register_forward_hook(make_hook(i))\n            hooks.append(h)\n\n        print(f"Registered {len(hooks)} hooks.")\n        return hooks\n\n    hooks = register_hooks(model, store)\n\n    # Verify immediately\n    store.clear()\n    test_input = tokenizer("test", return_tensors="pt").to(model.device)\n    with torch.no_grad():\n        _ = model(**test_input)\n    print(f"Verification — keys in store: {len(store.keys())} layers")\n    assert len(store.keys()) == N_LAYERS, f"Expected {N_LAYERS}, got {len(store.keys())}"\n    print("Hooks verified OK.")\n\n    # ---- 03, cell 7 (verbatim except where marked) ----\n    # -----------------------------------------------------------------------------\n    # CELL 6 — Text utilities\n    # -----------------------------------------------------------------------------\n    def clean_text(text: str) -> str:\n        return (text.replace("Ġ", " ")\n                    .replace("Ċ", "\\n")\n                    .replace("ĉ", "\\t"))\n\n\n    def get_analysis_text(trace: dict) -> str:\n        think = clean_text(trace.get("think_content", ""))\n        clean = clean_text(trace.get("response_clean", ""))\n        return think if think.strip() else clean\n\n\n    def word_idx_to_token_idx(\n        text: str,\n        word_idx: int,\n        tokenizer,\n        prompt_len: int\n    ) -> int:\n        """\n        Convert a word index in the analysis text to a token index in the\n        full model input (which includes the prompt prefix).\n\n        Strategy:\n        1. Split text into words\n        2. Reconstruct text up to word_idx\n        3. Tokenize that prefix to get token count\n        4. Add prompt_len offset\n\n        This is approximate but sufficient for ±30 token windows.\n        """\n        words  = text.split()\n        prefix = " ".join(words[:word_idx])\n        prefix_tokens = tokenizer(prefix, return_tensors="pt",\n                                  add_special_tokens=False)\n        n_prefix_tokens = prefix_tokens["input_ids"].shape[1]\n        return prompt_len + n_prefix_tokens\n\n    # ---- 03, cell 8 (verbatim except where marked) ----\n    # -----------------------------------------------------------------------------\n    # CELL 7 — Prompt builder (identical to notebook 01 to ensure same tokenization)\n    # -----------------------------------------------------------------------------\n    def build_prompt(problem: dict, tokenizer, model_name: str) -> str:\n        is_reasoning = any(tag in model_name for tag in ["R1", "QwQ"])\n\n        if problem.get("difficulty") == "hard":\n            instruction = (\n                "Solve the following competition mathematics problem carefully. "\n                "Show your reasoning step by step and verify your answer."\n            )\n        else:\n            instruction = (\n                "Solve the following mathematics competition problem. "\n                "Show your working step by step."\n            )\n\n        if is_reasoning:\n            messages = [{"role": "user",\n                         "content": f"{instruction}\\n\\nProblem: {problem[\'problem\']}"}]\n        else:\n            messages = [\n                {"role": "system",\n                 "content": "You are an expert mathematician. Solve problems with "\n                            "clear step-by-step reasoning."},\n                {"role": "user",\n                 "content": f"{instruction}\\n\\nProblem: {problem[\'problem\']}"}\n            ]\n\n        return tokenizer.apply_chat_template(\n            messages, tokenize=False, add_generation_prompt=True\n        )\n\n    # ---- 03, cell 9 (verbatim except where marked) ----\n    # -----------------------------------------------------------------------------\n    # CELL 8 — Core extraction: run model and extract windows\n    # -----------------------------------------------------------------------------\n    @torch.no_grad()\n    def extract_windows_for_problem(\n        trace: dict,\n        label: dict,\n        model,\n        tokenizer,\n        store: ActivationStore,\n        n_layers: int,\n        window_tokens: int\n    ) -> dict | None:\n        """\n        Extracts activation windows for a given problem based on revision labels.\n        """\n        pid        = trace["problem_id"]\n        analysis   = get_analysis_text(trace)\n        prompt     = build_prompt(trace, tokenizer, MODEL_NAME)\n        inputs     = tokenizer(prompt, return_tensors="pt", truncation=False).to(model.device)\n        prompt_len = inputs["input_ids"].shape[1]\n\n        # Generate full input IDs for the model run\n        full_text   = prompt + analysis\n        full_inputs = tokenizer(full_text, return_tensors="pt", truncation=False).to(model.device)\n        seq_len     = full_inputs["input_ids"].shape[1]\n\n        # Convert revision word indices to token indices\n        revision_entries = []\n        for rev in label.get("revisions", []):\n            word_idx       = rev.get("revision_word_idx", 0)\n            ctrl_word_idx  = rev.get("control_word_idx", 0)\n\n            token_idx      = word_idx_to_token_idx(\n                analysis, word_idx, tokenizer, prompt_len\n            )\n            ctrl_token_idx = word_idx_to_token_idx(\n                analysis, ctrl_word_idx, tokenizer, prompt_len\n            )\n\n            # Clamp to valid range\n            token_idx      = max(window_tokens, min(token_idx,      seq_len - window_tokens - 1))\n            ctrl_token_idx = max(window_tokens, min(ctrl_token_idx, seq_len - window_tokens - 1))\n            revision_entries.append({\n                "token_idx":      token_idx,\n                "ctrl_token_idx": ctrl_token_idx,   # ← this was missing\n                "verdict":        rev.get("verdict", "UNKNOWN"),\n                "confidence":     rev.get("confidence", 0.0),\n                "word_idx":       word_idx,\n            })\n        if not revision_entries:\n            return None # No valid revisions to extract\n\n        # Run model forward pass to populate store\n        store.clear()\n        _ = model(**full_inputs, output_hidden_states=False)\n\n        # Instead of pre-allocating the full array upfront:\n        # OLD — causes OOM on large n_revisions:\n        # revision_windows = np.zeros((n_revisions, n_layers, window_size, HIDDEN_DIM), dtype=np.float16)\n\n        # NEW — build list, stack at end:\n        revision_windows_list = []\n        control_windows_list  = [] # Control windows are not defined in the trace, commenting out\n        revision_norms_list   = []\n        control_norms_list    = [] # Control windows are not defined in the trace, commenting out\n\n        window_size = 2 * window_tokens + 1\n\n        for r, entry in enumerate(revision_entries):\n            t_rev  = entry["token_idx"]\n            t_ctrl = entry["ctrl_token_idx"] # Control tokens are not defined in the trace, commenting out\n\n            rev_win_layers  = np.zeros((n_layers, window_size, HIDDEN_DIM), dtype=np.float16)\n            ctrl_win_layers = np.zeros((n_layers, window_size, HIDDEN_DIM), dtype=np.float16) # Control windows are not defined in the trace, commenting out\n            rev_norms       = np.zeros(n_layers, dtype=np.float32)\n            ctrl_norms      = np.zeros(n_layers, dtype=np.float32) # Control windows are not defined in the trace, commenting out\n\n            for l in range(n_layers):\n                hidden = store[l]   # (seq_len, hidden_dim)\n\n                rev_window = hidden[t_rev - window_tokens: t_rev + window_tokens + 1]\n                if rev_window.shape[0] == window_size:\n                    rev_win_layers[l] = rev_window.numpy().astype(np.float16)\n\n                ctrl_window = hidden[t_ctrl - window_tokens: t_ctrl + window_tokens + 1] # Control windows are not defined in the trace, commenting out\n                if ctrl_window.shape[0] == window_size:\n                     ctrl_win_layers[l] = ctrl_window.numpy().astype(np.float16) # Control windows are not defined in the trace, commenting out\n\n                if l > 0:\n                    prev = store[l-1]\n                    rev_norms[l]  = float(torch.norm(hidden[t_rev]  - prev[t_rev]).item())\n                    # ctrl_norms[l] = float(torch.norm(hidden[t_ctrl] - prev[t_ctrl]).item()) # Control windows are not defined in the trace, commenting out\n\n            revision_windows_list.append(rev_win_layers)\n            control_windows_list.append(ctrl_win_layers) # Control windows are not defined in the trace, commenting out\n            revision_norms_list.append(rev_norms)\n            control_norms_list.append(ctrl_norms) # Control windows are not defined in the trace, commenting out\n\n        # Stack into final arrays\n        revision_windows = np.stack(revision_windows_list)  # (n_rev, n_layers, 61, hidden_dim)\n        control_windows  = np.stack(control_windows_list) # Control windows are not defined in the trace, commenting out\n        revision_norms   = np.stack(revision_norms_list)    # (n_rev, n_layers)\n        control_norms    = np.stack(control_norms_list) # Control windows are not defined in the trace, commenting out\n\n        store.clear()\n        torch.cuda.empty_cache()\n        gc.collect()\n        revision_meta = [\n            {\n                "token_idx":      entry["token_idx"],\n                "ctrl_token_idx": entry["ctrl_token_idx"],\n                "verdict":        entry.get("verdict", "UNKNOWN"),\n                "confidence":     entry.get("confidence", 0.0),\n                "word_idx":       entry.get("word_idx", 0),\n            }\n            for entry in revision_entries\n        ]\n\n        return {\n            "problem_id":       pid,\n            "model":            MODEL_SHORT,\n            "difficulty":       trace.get("difficulty", "unknown"),\n            "is_baseline":      False,\n            "n_revisions":      len(revision_entries),\n            "n_layers":         n_layers,\n            "hidden_dim":       HIDDEN_DIM,\n            "window_tokens":    window_tokens,\n            "revision_meta":    revision_meta,\n            "revision_windows": np.nan_to_num(revision_windows, nan=0.0, posinf=0.0, neginf=0.0),\n            "control_windows":  np.nan_to_num(control_windows,  nan=0.0, posinf=0.0, neginf=0.0),\n            "revision_norms":   revision_norms,\n            "control_norms":    control_norms,\n        }\n\n    # ---- 03, cell 10 (verbatim except where marked) ----\n    # -----------------------------------------------------------------------------\n    # CELL 9 — Baseline extraction for Llama (random windows)\n    # Only runs when IS_BASELINE_MODEL = True\n    # -----------------------------------------------------------------------------\n    @torch.no_grad()\n    def extract_baseline_windows(\n        trace: dict,\n        model,\n        tokenizer,\n        store: ActivationStore,\n        n_layers: int,\n        window: int,\n        n_windows: int,\n        rng: random.Random\n    ) -> dict | None:\n        """\n        For Llama baseline: extract N random token windows from each trace.\n        No revision labels needed — just random positions in the response.\n        """\n        pid         = trace["problem_id"]\n        analysis    = get_analysis_text(trace)\n        prompt      = build_prompt(trace, tokenizer, MODEL_NAME)\n        inputs      = tokenizer(prompt, return_tensors="pt",\n                                truncation=False).to(model.device)\n        prompt_len  = inputs["input_ids"].shape[1]\n\n        full_text   = prompt + analysis\n        full_inputs = tokenizer(full_text, return_tensors="pt",\n                                truncation=False).to(model.device)\n        seq_len     = full_inputs["input_ids"].shape[1]\n\n        if seq_len <= 2 * window + prompt_len + 10:\n            return None   # trace too short for any window\n\n        store.clear()\n        _ = model(**full_inputs, output_hidden_states=False)\n\n        # Sample random positions in the response portion only\n        valid_range  = range(prompt_len + window, seq_len - window - 1)\n        if len(valid_range) < n_windows:\n            positions = list(valid_range)\n        else:\n            positions = rng.sample(list(valid_range), n_windows)\n\n        window_size = 2 * window + 1\n        n_pos       = len(positions)\n\n        baseline_windows = np.zeros(\n            (n_pos, n_layers, window_size, HIDDEN_DIM), dtype=np.float16\n        )\n        baseline_norms   = np.zeros((n_pos, n_layers), dtype=np.float32)\n\n        for p_idx, t in enumerate(positions):\n            for l in range(n_layers):\n                hidden = store[l]\n                win    = hidden[t - window: t + window + 1]\n                if win.shape[0] == window_size:\n                    baseline_windows[p_idx, l] = win.numpy().astype(np.float16)\n                if l > 0:\n                    prev    = store[l-1]\n                    delta   = hidden[t] - prev[t]\n                    baseline_norms[p_idx, l] = float(torch.norm(delta).item())\n\n        store.clear()\n        torch.cuda.empty_cache()\n        gc.collect()\n\n        return {\n            "problem_id":       pid,\n            "model":            MODEL_SHORT,\n            "difficulty":       trace.get("difficulty", "unknown"),\n            "is_baseline":      True,\n            "n_windows":        n_pos,\n            "n_layers":         n_layers,\n            "hidden_dim":       HIDDEN_DIM,\n            "window_tokens":    window,\n            "positions":        positions,\n            "baseline_windows": baseline_windows,   # (n_pos, n_layers, 61, hidden_dim)\n            "baseline_norms":   baseline_norms,     # (n_pos, n_layers)\n        }\n\n    # ---- 03, cell 11 (verbatim except where marked) ----\n    # -----------------------------------------------------------------------------\n    # CELL 10 — Save and load functions\n    # -----------------------------------------------------------------------------\n    def save_activations(result: dict, activ_dir: Path):\n        """\n        Save activation arrays as compressed .npz and metadata as .json.\n        Keeps arrays and metadata separate for efficient loading downstream.\n        """\n        pid = result["problem_id"]\n\n        # Save arrays\n        array_keys = [k for k, v in result.items() if isinstance(v, np.ndarray)]\n        arrays     = {k: result[k] for k in array_keys}\n        np.savez_compressed(activ_dir / f"{pid}.npz", **arrays)\n\n        # Save metadata (everything that\'s not an array)\n        meta = {k: v for k, v in result.items() if not isinstance(v, np.ndarray)}\n        with open(activ_dir / f"{pid}_meta.json", "w") as f:\n            json.dump(meta, f, indent=2)\n\n\n    def load_activations(pid: str, activ_dir: Path) -> tuple[dict, dict]:\n        """\n        Load arrays and metadata for one problem.\n        """\n        arrays = dict(np.load(activ_dir / f"{pid}.npz"))\n        with open(activ_dir / f"{pid}_meta.json") as f:\n            meta = json.load(f)\n        return arrays, meta\n\n    # ---- 03, cell 12 (verbatim except where marked) ----\n    # -----------------------------------------------------------------------------\n    # CELL 11 — Checkpoint log\n    # -----------------------------------------------------------------------------\n    def load_extraction_log() -> dict:\n        if LOG_FILE.exists():\n            with open(LOG_FILE) as f:\n                log = json.load(f)\n            print(f"Resuming. Done: {len(log[\'completed\'])} | "\n                  f"Skipped: {len(log[\'skipped\'])} | Failed: {len(log[\'failed\'])}")\n        else:\n            log = {\n                "model":       MODEL_SHORT,\n                "is_baseline": IS_BASELINE_MODEL,\n                "started":     datetime.now().isoformat(),\n                "completed":   [],\n                "skipped":     [],\n                "failed":      [],\n            }\n            print("Starting fresh extraction run.")\n        return log\n\n\n    def save_extraction_log(log: dict):\n        with open(LOG_FILE, "w") as f:\n            json.dump(log, f, indent=2)\n\n    # ---- 03, cell 13 (verbatim except where marked) ----\n    # -----------------------------------------------------------------------------\n    # CELL 12 — Build work queue\n    # For reasoning models: pair trace files with label files.\n    # For baseline model: use all non-truncated trace files directly.\n    # -----------------------------------------------------------------------------\n    def build_work_queue(\n        trace_dir: Path,\n        label_dir: Path,\n        is_baseline: bool,\n        completed: list\n    ) -> list[tuple]:\n        """\n        Returns list of (trace, label_or_None) tuples to process.\n        """\n        done = set(completed)\n        trace_files = [f for f in trace_dir.glob("*.json")\n                       if f.name != "run_log.json"]\n\n        queue = []\n        print(len(trace_files))\n\n        if is_baseline:\n            # Baseline: all non-truncated traces, no labels needed\n            for tf in trace_files:\n                with open(tf) as f:\n                    trace = json.load(f)\n                if \'problem_id\' not in trace:\n                    print(f"Skipping trace {tf.name}: \'problem_id\' key missing.")\n                    continue\n                if trace.get("truncated"):\n                    continue\n                if trace["problem_id"] in done:\n                    continue\n                queue.append((trace, None))\n        else:\n            # Reasoning models: only traces with a valid label file\n            label_files = {f.stem: f for f in label_dir.glob("*.json")\n                           if f.name != "labeling_log.json"\n                           and f.name != "label_summary.json"}\n\n            for tf in trace_files:\n                with open(tf) as f:\n                    trace = json.load(f)\n\n                if \'problem_id\' not in trace:\n                    print(f"Skipping trace {tf.name}: \'problem_id\' key missing.")\n                    continue\n\n                pid = trace["problem_id"]\n\n                if pid in done:\n                    continue\n                if pid not in label_files:\n                    continue   # no label — skipped in notebook 02\n\n                with open(label_files[pid]) as f:\n                    label = json.load(f)\n\n                if label.get("skipped"):\n                    continue   # notebook 02 decided to skip this trace\n\n                queue.append((trace, label))\n\n        return queue\n\n\n    log   = load_extraction_log()\n    queue = build_work_queue(\n        TRACE_DIR, LABEL_DIR,\n        IS_BASELINE_MODEL,\n        log["completed"] + log["skipped"]\n    )\n    print(f"Work queue: {len(queue)} problems to extract")\n\n    # ---- 03, cell 14 (verbatim except where marked) ----\n    # -----------------------------------------------------------------------------\n    # CELL 13 — Main extraction loop\n    # -----------------------------------------------------------------------------\n    rng = random.Random(RANDOM_SEED)\n\n    # Estimate storage before starting\n    if not IS_BASELINE_MODEL and queue:\n        sample_label = queue[0][1]\n        avg_rev_est  = sum(\n            l.get("n_verified", 0) for _, l in queue if l\n        ) / max(len(queue), 1)\n        window_size  = 2 * WINDOW_TOKENS + 1\n        est_gb       = (len(queue) * avg_rev_est * N_LAYERS\n                        * window_size * HIDDEN_DIM * 2) / 1024**3\n        print(f"Estimated storage: {est_gb:.1f} GB")\n        print(f"  ({len(queue)} problems × {avg_rev_est:.1f} revisions × "\n              f"{N_LAYERS} layers × {window_size} tokens × {HIDDEN_DIM} dims × 2 bytes)")\n\n    print(f"\\nStarting extraction: {len(queue)} problems")\n    print(f"Model: {MODEL_NAME}")\n    print(f"Baseline mode: {IS_BASELINE_MODEL}")\n    print("=" * 65)\n\n    total_revisions_extracted = 0\n    for i, (trace, label) in enumerate(queue):\n        pid  = trace["problem_id"]\n        diff = trace.get("difficulty", "?")\n        print(f"\\n[{i+1}/{len(queue)}] {pid}  diff={diff}")\n\n        t0 = time.time()\n        try:\n            if IS_BASELINE_MODEL:\n                result = extract_baseline_windows(\n                    trace, model, tokenizer, store,\n                    N_LAYERS, WINDOW_TOKENS,\n                    N_BASELINE_WINDOWS // max(len(queue), 1) + 1,\n                    rng\n                )\n            else:\n                result = extract_windows_for_problem(\n                    trace, label, model, tokenizer, store,\n                    N_LAYERS, WINDOW_TOKENS\n                )\n\n            if result is None:\n                log["skipped"].append(pid)\n                save_extraction_log(log)\n                print(f"  SKIPPED: no valid windows")\n                continue\n\n            save_activations(result, ACTIV_DIR)\n            log["completed"].append(pid)\n            save_extraction_log(log)\n\n            elapsed = time.time() - t0\n            if IS_BASELINE_MODEL:\n                n_extracted = result["n_windows"]\n            else:\n                n_extracted = result["n_revisions"]\n                total_revisions_extracted += n_extracted\n\n            # Estimate file size\n            total_elements = sum(\n                v.size for v in result.values() if isinstance(v, np.ndarray)\n            )\n            est_mb = total_elements * 2 / 1024**2   # float16 = 2 bytes\n\n            print(f"  ✓ {n_extracted} windows | "\n                  f"~{est_mb:.1f} MB | {elapsed:.1f}s")\n\n        except Exception as e:\n            print(f"  FAILED: {e}")\n            import traceback\n            traceback.print_exc()\n            log["failed"].append({"problem_id": pid, "error": str(e)})\n            save_extraction_log(log)\n            # Clear memory even on failure\n            store.clear()\n            torch.cuda.empty_cache()\n            gc.collect()\n\n    print("\\n" + "=" * 65)\n    print(f"Extraction complete.")\n    print(f"  Completed : {len(log[\'completed\'])}")\n    print(f"  Skipped   : {len(log[\'skipped\'])}")\n    print(f"  Failed    : {len(log[\'failed\'])}")\n    if not IS_BASELINE_MODEL:\n        print(f"  Total revision windows extracted: {total_revisions_extracted}")\n\n    # ---- 03, cell 15 (verbatim except where marked) ----\n    # -----------------------------------------------------------------------------\n    # CELL 14 — Storage audit and cross-model summary\n    # Run after extraction completes. Checks actual disk usage and validates\n    # all .npz files are readable before moving on.\n    # -----------------------------------------------------------------------------\n    def storage_audit(activ_dir: Path, model_short: str) -> dict:\n        npz_files = list(activ_dir.glob("*.npz"))\n        if not npz_files:\n            print("No .npz files found.")\n            return {}\n\n        total_bytes     = 0\n        total_revisions = 0\n        total_problems  = 0\n        corrupt_files   = []\n        by_diff         = defaultdict(lambda: {"problems": 0, "revisions": 0, "bytes": 0})\n\n        for npz_path in npz_files:\n            pid       = npz_path.stem\n            meta_path = activ_dir / f"{pid}_meta.json"\n\n            # Check file is readable\n            try:\n                arrays = np.load(npz_path)\n                _ = list(arrays.keys())   # force load\n            except Exception as e:\n                corrupt_files.append({"pid": pid, "error": str(e)})\n                continue\n\n            file_bytes = npz_path.stat().st_size\n            total_bytes += file_bytes\n\n            # Load metadata\n            if meta_path.exists():\n                with open(meta_path) as f:\n                    meta = json.load(f)\n                diff = meta.get("difficulty", "unknown")\n                n_rev = meta.get("n_revisions", meta.get("n_windows", 0))\n            else:\n                diff  = "unknown"\n                n_rev = 0\n\n            by_diff[diff]["problems"]   += 1\n            by_diff[diff]["revisions"]  += n_rev\n            by_diff[diff]["bytes"]      += file_bytes\n            total_revisions += n_rev\n            total_problems  += 1\n\n        total_gb = total_bytes / 1024**3\n\n        print(f"\\n{\'=\'*65}")\n        print(f"STORAGE AUDIT — {model_short}")\n        print(f"{\'=\'*65}")\n        print(f"  Total problems:   {total_problems}")\n        print(f"  Total revisions:  {total_revisions}")\n        print(f"  Total size:       {total_gb:.2f} GB")\n        print(f"  Corrupt files:    {len(corrupt_files)}")\n\n        for diff, stats in by_diff.items():\n            gb = stats["bytes"] / 1024**3\n            print(f"\\n  {diff.upper()}")\n            print(f"    Problems:   {stats[\'problems\']}")\n            print(f"    Revisions:  {stats[\'revisions\']}")\n            print(f"    Size:       {gb:.2f} GB")\n\n        if corrupt_files:\n            print(f"\\n  ⚠ CORRUPT FILES — re-extract these:")\n            for c in corrupt_files:\n                print(f"    {c[\'pid\']}: {c[\'error\']}")\n\n        summary = {\n            "model":           model_short,\n            "timestamp":       datetime.now().isoformat(),\n            "total_problems":  total_problems,\n            "total_revisions": total_revisions,\n            "total_gb":        round(total_gb, 2),\n            "corrupt_files":   corrupt_files,\n            "by_difficulty":   {\n                d: {k: v for k, v in s.items() if k != "bytes"}\n                for d, s in by_diff.items()\n            }\n        }\n\n        # Save per-model audit\n        audit_path = activ_dir / "storage_audit.json"\n        with open(audit_path, "w") as f:\n            json.dump(summary, f, indent=2)\n        print(f"\\n  Audit saved: {audit_path}")\n\n        # Append to cross-model summary\n        if SUMMARY_FILE.exists():\n            with open(SUMMARY_FILE) as f:\n                cross = json.load(f)\n        else:\n            cross = {}\n        cross[model_short] = summary\n        with open(SUMMARY_FILE, "w") as f:\n            json.dump(cross, f, indent=2)\n        print(f"  Cross-model summary updated: {SUMMARY_FILE}")\n\n        return summary\n\n\n    storage_audit(ACTIV_DIR, MODEL_SHORT)\n    for _h in hooks: _h.remove()\n    del model; gc.collect(); torch.cuda.empty_cache()\n\n\n# #############################################################################\n# STAGE "filler" — notebook 05, verbatim (Llama-8B, new output folder)\n# #############################################################################\nif "filler" in STAGES:\n    MODEL_NAME = "deepseek-ai/DeepSeek-R1-Distill-Llama-8B"\n    # ---- 05, cell 2 (verbatim except where marked) ----\n    # =============================================================================\n    # 05 -- FILLER ACTIVATION EXTRACTION\n    #\n    # Extracts activation windows at confirmed-filler positions\n    # (rejects/{model}_confirmed_filler.json, from notebook 04) with the same\n    # hooks and window logic as notebook 03, writing\n    # activations_filler/{model}/{problem_id}.npz.\n    #\n    # NOTE ON DATA COMPLETENESS: if ANY layer\'s window comes up short near a\n    # sequence boundary for a given filler event, that event is dropped entirely\n    # (not zero-padded) -- see the `ok` flag in the extraction loop. This means\n    # activations_filler/ has FEWER events than rejects/{model}_confirmed_filler.json\n    # lists. Do not assume 1:1 correspondence between the two without checking.\n    #\n    # NOTE ON METADATA: filler_meta only carries marker, token_idx, matched_text.\n    # char_start / type_hint / filler_confidence are NOT duplicated into the\n    # activation metadata -- cross-reference rejects/{model}_confirmed_filler.json\n    # by matched_text/token position if those fields are needed downstream.\n    # =============================================================================\n\n    import torch, json, gc, numpy as np\n    from pathlib import Path\n    from transformers import AutoTokenizer, AutoModelForCausalLM\n\n    MODEL_SHORT = MODEL_NAME.split("/")[-1]\n    WINDOW      = 30\n\n    GDRIVE_BASE = DATA_ROOT\n\n    # ---- 05, cell 3 (verbatim except where marked) ----\n    REJECT_BASE = GDRIVE_BASE / "rejects"\n    TRACE_DIR   = GDRIVE_BASE / "traces" / MODEL_SHORT\n    OUT_DIR     = GDRIVE_BASE / NEW_FIL / MODEL_SHORT   # CHANGED: new folder\n    OUT_DIR.mkdir(parents=True, exist_ok=True)\n\n    tokenizer = AutoTokenizer.from_pretrained(MODEL_NAME, trust_remote_code=True)\n    if tokenizer.pad_token is None:\n        tokenizer.pad_token = tokenizer.eos_token\n    model = AutoModelForCausalLM.from_pretrained(\n        MODEL_NAME, torch_dtype=torch.float16, device_map="auto", trust_remote_code=True)\n\n    # ---- 05, cell 4 (verbatim except where marked) ----\n    model.eval()\n    N_LAYERS   = model.config.num_hidden_layers\n    HIDDEN_DIM = model.config.hidden_size\n\n    store = {}\n    hooks = []\n    for i, layer in enumerate(model.model.layers):\n        def mk(idx):\n            def hook(mod, inp, out):\n                h = out[0]\n                store[idx] = (h[0] if h.dim() == 3 else h).detach().cpu().float()\n            return hook\n        hooks.append(layer.register_forward_hook(mk(i)))\n    print(f"{N_LAYERS} hooks registered")\n\n    # ---- 05, cell 5 (verbatim except where marked) ----\n    def clean_text(t):\n        return t.replace("Ġ"," ").replace("Ċ","\\n").replace("ĉ","\\t")\n    def get_analysis_text(tr):\n        th = clean_text(tr.get("think_content",""))\n        cl = clean_text(tr.get("response_clean",""))\n        return th if th.strip() else cl\n    def build_prompt(tr):\n        instr = ("Solve the following competition mathematics problem carefully. "\n                 "Show your reasoning step by step and verify your answer."\n                 if tr.get("difficulty")=="hard" else\n                 "Solve the following mathematics competition problem. "\n                 "Show your working step by step.")\n        msgs = [{"role":"user","content":f"{instr}\\n\\nProblem: {tr[\'problem\']}"}]\n        return tokenizer.apply_chat_template(msgs, tokenize=False, add_generation_prompt=True)\n    def word_to_token(text, widx, plen):\n        pref = " ".join(text.split()[:widx])\n        return plen + tokenizer(pref, return_tensors="pt",\n                                add_special_tokens=False)["input_ids"].shape[1]\n\n    with open(REJECT_BASE / f"{MODEL_SHORT}_confirmed_filler.json") as f:\n        fillers = json.load(f)\n\n    by_problem = {}\n    for r in fillers:\n        by_problem.setdefault(r["problem_id"], []).append(r)\n\n    # ---- 05, cell 6 (verbatim except where marked) ----\n    print(f"{len(fillers)} filler positions across {len(by_problem)} problems")\n\n    for i, (pid, entries) in enumerate(sorted(by_problem.items())):\n        if (OUT_DIR / f"{pid}.npz").exists():\n            continue\n        try:\n            with open(TRACE_DIR / f"{pid}.json") as f:\n                trace = json.load(f)\n            analysis = get_analysis_text(trace)\n            prompt   = build_prompt(trace)\n            plen = tokenizer(prompt, return_tensors="pt")["input_ids"].shape[1]\n            full = tokenizer(prompt + analysis, return_tensors="pt").to(model.device)\n            slen = full["input_ids"].shape[1]\n\n            store.clear()\n            with torch.no_grad():\n                _ = model(**full)\n\n            wins, metas = [], []\n            for e in entries:\n                t = word_to_token(analysis, e["word_idx"], plen)\n                t = max(WINDOW, min(t, slen - WINDOW - 1))\n                w = np.zeros((N_LAYERS, 2*WINDOW+1, HIDDEN_DIM), dtype=np.float16)\n                ok = True\n                for l in range(N_LAYERS):\n                    sl = store[l][t-WINDOW : t+WINDOW+1]\n                    if sl.shape[0] != 2*WINDOW+1:\n                        ok = False; break\n                    w[l] = sl.numpy().astype(np.float16)\n                if ok:\n                    wins.append(np.nan_to_num(w, nan=0., posinf=0., neginf=0.))\n                    metas.append({"marker": e["marker"], "token_idx": int(t),\n                                  "matched_text": e["matched_text"]})\n            store.clear(); torch.cuda.empty_cache(); gc.collect()\n\n            if not wins:\n                continue\n            np.savez_compressed(OUT_DIR / f"{pid}.npz",\n                                filler_windows=np.stack(wins))\n            with open(OUT_DIR / f"{pid}_meta.json", "w") as f:\n                json.dump({"problem_id": pid, "n_layers": N_LAYERS,\n                           "hidden_dim": HIDDEN_DIM, "difficulty": trace.get("difficulty"),\n                           "filler_meta": metas}, f, indent=2)\n            print(f"[{i+1}/{len(by_problem)}] {pid}: {len(wins)} filler windows")\n        except Exception as ex:\n            print(f"[{i+1}] {pid} FAILED: {ex}")\n            store.clear(); torch.cuda.empty_cache(); gc.collect()\n\n    print("Filler extraction done ->", OUT_DIR)\n    for _h in hooks: _h.remove()\n    del model; gc.collect(); torch.cuda.empty_cache()\n\n\n# #############################################################################\n# STAGE "verify" — CPU, tokenizer only. Changes nothing.\n# #############################################################################\nif "verify" in STAGES:\n    import numpy as np\n    from collections import Counter\n    from transformers import AutoTokenizer\n    CENTER = 30\n    tok = AutoTokenizer.from_pretrained(f"deepseek-ai/{LLAMA}", trust_remote_code=True)\n    pf = json.load(open(DATA_ROOT / "results_v3" / "task1_residual_pointfix.json"))\n    L = int(pf[LLAMA]["peak_layer"])\n    import shutil, time, tempfile\n    LOCAL_TMP = Path(tempfile.gettempdir()) / "verify_npz"; LOCAL_TMP.mkdir(exist_ok=True)\n    def load_layer(path, key, layer):\n        """One layer of an .npz on Drive. Copies the file to local disk first and\n        retries on Drive I/O errors (Errno 5 / 107 / 103 / 108), remounting\n        between attempts. Returns None if it still cannot be read."""\n        for attempt in range(5):\n            tmp = LOCAL_TMP / path.name\n            try:\n                shutil.copyfile(path, tmp)\n                with np.load(tmp) as z:\n                    return z[key][:, layer, :, :].astype(np.float32)\n            except Exception as e:\n                err = getattr(e, "errno", None) or getattr(getattr(e, "__context__", None), "errno", None)\n                print(f"    read failed ({type(e).__name__}, errno {err}) on {path.name}, attempt {attempt+1}/5", flush=True)\n                time.sleep(10 * (attempt + 1))\n                try:\n                    from google.colab import drive; drive.mount("/content/gdrive", force_remount=True)\n                except Exception:\n                    pass\n            finally:\n                try: tmp.unlink()\n                except Exception: pass\n        return None\n    def rj(p, d=None):\n        try: return json.load(open(p))\n        except Exception: return d\n    def clean_text(t): return t.replace("Ġ", " ").replace("Ċ", "\\n").replace("ĉ", "\\t")\n    def analysis(tr):\n        th = clean_text(tr.get("think_content", "") or ""); cl = clean_text(tr.get("response_clean", "") or "")\n        return th if th.strip() else cl\n    def prompt_of(tr):\n        instr = ("Solve the following competition mathematics problem carefully. "\n                 "Show your reasoning step by step and verify your answer."\n                 if tr.get("difficulty") == "hard" else\n                 "Solve the following mathematics competition problem. Show your working step by step.")\n        return tok.apply_chat_template([{"role": "user", "content": f"{instr}\\n\\nProblem: {tr[\'problem\']}"}],\n                                       tokenize=False, add_generation_prompt=True)\n    rejects = {}\n    for r in rj(DATA_ROOT / "rejects" / f"{LLAMA}_confirmed_filler.json", []) or []:\n        rejects.setdefault(str(r["problem_id"]), []).append(r)\n    report = {}\n    for arm, old_dir, new_dir, wkey, mkey in (\n            ("revision", DATA_ROOT / "activations" / LLAMA, DATA_ROOT / NEW_REV / LLAMA, "revision_windows", "revision_meta"),\n            ("filler", DATA_ROOT / "activations_filler" / LLAMA, DATA_ROOT / NEW_FIL / LLAMA, "filler_windows", "filler_meta")):\n        st = Counter(); d_marker, d_old_new, cos_same, best_off, best_cos = [], [], [], [], []\n        unreadable = []\n        new_metas = sorted(new_dir.glob("*_meta.json"))\n        n_old = sum(len((rj(p, {}) or {}).get(mkey) or []) for p in old_dir.glob("*_meta.json"))\n        for mp in new_metas:\n            pid = mp.name[:-len("_meta.json")]\n            nm = (rj(mp, {}) or {}).get(mkey) or []\n            om = (rj(old_dir / mp.name, {}) or {}).get(mkey) or []\n            tr = rj(DATA_ROOT / "traces" / LLAMA / f"{pid}.json")\n            if tr is None: st["no trace"] += 1; continue\n            text = analysis(tr); prompt = prompt_of(tr)\n            enc = tok(prompt + text, return_offsets_mapping=True); offs = enc["offset_mapping"]; seq = len(enc["input_ids"])\n            plen = len(tok(prompt)["input_ids"]); plen_c = len(prompt)\n            if arm == "revision":\n                srows = [r for r in ((rj(DATA_ROOT / "labels" / LLAMA / f"{pid}.json", {}) or {}).get("revisions") or [])]\n            else:\n                srows = rejects.get(pid, [])\n            NW = load_layer(new_dir / f"{pid}.npz", wkey, L)\n            if NW is None:\n                st["NEW file unreadable after 5 tries (skipped; re-run verify)"] += 1; unreadable.append(f"new/{pid}"); continue\n            OW = None\n            if (old_dir / f"{pid}.npz").exists():\n                OW = load_layer(old_dir / f"{pid}.npz", wkey, L)\n                if OW is None:\n                    st["old file unreadable after 5 tries (old-vs-new skipped for it)"] += 1; unreadable.append(f"old/{pid}")\n            for i, m in enumerate(nm):\n                # 1. recomputed centre == stored (the check Llama-8B failed before)\n                src = srows[i] if (arm == "revision" and i < len(srows)) else None\n                if arm == "filler":   # 05 may drop events; match on matched_text in order\n                    src = next((r for r in srows if r.get("matched_text") == m.get("matched_text")\n                                and not r.get("_used")), None)\n                    if src is not None: src["_used"] = True\n                w = (src or {}).get("revision_word_idx" if arm == "revision" else "word_idx")\n                if w is not None:\n                    t = plen + len(tok(" ".join(text.split()[:int(w)]), add_special_tokens=False)["input_ids"])\n                    t = max(CENTER, min(t, seq - CENTER - 1))\n                    st[f"recomputed centre {\'==\' if t == int(m[\'token_idx\']) else \'!=\'} stored"] += 1\n                # 2. where the new centre sits relative to the marker\'s first token\n                cs = (src or {}).get("char_start")\n                if cs is not None:\n                    pos = plen_c + int(cs)\n                    mt = next((k for k, (a, b) in enumerate(offs) if a <= pos < b and b > a), None)\n                    if mt is not None: d_marker.append(int(m["token_idx"]) - mt)\n                # 3. old vs new window for the same event (same file, same row)\n                if OW is not None and i < len(om) and i < OW.shape[0]:\n                    d_old_new.append(int(om[i]["token_idx"]) - int(m["token_idx"]))\n                    oc = OW[i, CENTER] / (np.linalg.norm(OW[i, CENTER]) + 1e-9)\n                    nw = NW[i] / (np.linalg.norm(NW[i], axis=1, keepdims=True) + 1e-9)\n                    cos = nw @ oc\n                    cos_same.append(float(cos[CENTER])); k = int(cos.argmax())\n                    best_off.append(k - CENTER); best_cos.append(float(cos[k]))\n        def dist(a):\n            if not a: return None\n            a = np.array(a); return {"n": int(len(a)), "median": float(np.median(a)), "min": float(a.min()),\n                                     "max": float(a.max()), "most_common": Counter(a.round(3).tolist()).most_common(8)}\n        bc = np.array(best_cos) if best_cos else np.array([])\n        report[arm] = {"events_new": sum(len((rj(p, {}) or {}).get(mkey) or []) for p in new_metas),\n                       "events_old": n_old, "checks": dict(st),\n                       "new_centre_minus_marker_first_token": dist(d_marker),\n                       "share_new_centre_in_-3..+1": (float(np.mean([(-3 <= x <= 1) for x in d_marker])) if d_marker else None),\n                       "old_token_idx_minus_new": dist(d_old_new),\n                       "cos_old_centre_vs_new_centre": dist(cos_same),\n                       "old_centre_found_in_new_window (cos>0.99)": (float(np.mean(bc > 0.99)) if len(bc) else None),\n                       "offset_of_best_match_in_new_window": dist(best_off),\n                       "unreadable_files": unreadable}\n        print(f"\\n  {arm}: {json.dumps(report[arm], default=str)}")\n    json.dump(report, open(DATA_ROOT / "hand_labeling_export" / "llama8b_reextract_verification.json", "w"),\n              indent=1, default=str)\n    print("\\n  wrote hand_labeling_export/llama8b_reextract_verification.json")\n\n\n# #############################################################################\n# STAGE "direction" — notebook 08 cell 1 (steering direction), verbatim, on the\n# re-extracted Llama-8B windows. CPU. Writes a NEW file,\n# hand_labeling_export/steering_directions_llama8b_reextract.json; the\n# published steering_directions.json is untouched. Then compares the two.\n# The strength multiplier (CHOSEN_ALPHA_MULTIPLIER, Llama-8B 1.5) is NOT\n# re-chosen: 09 applies the published multiplier to the new direction\'s norm.\n# #############################################################################\nif "direction" in STAGES:\n    # ---- 08, cell 1 (verbatim except where marked) ----\n    # =============================================================================\n    # EXTRACT STEERING DIRECTIONS -- diff-of-means from existing saved activations\n    #\n    # direction = mean(revision_windows[center]) - mean(filler_windows[center])\n    #\n    # Uses revision_windows (activations/) and filler_windows (activations_filler/)\n    # -- the SAME classes as the probe\'s MATCHED contrast (revision-marker vs\n    # filler-marker, same lexical marker family) -- not the generic\n    # \'control_windows\' field also present in activations/*.npz, which is a\n    # weaker, non-lexically-matched contrast. Staying consistent with the\n    # project\'s established lexical-confound-aware approach.\n    #\n    # Layer: does NOT depend on the probe\'s saved results JSON (path/existence\n    # unconfirmed, would be a fragile dependency). Instead uses a simple,\n    # self-contained heuristic grounded in the already-established finding that\n    # the accuracy plateau begins ~32-38% of network depth across all four\n    # models: picks a layer at 65% depth (comfortably inside the plateau, not\n    # near either edge). n_layers is read directly from the activation array\n    # shape, so this needs no external file at all.\n    #\n    # Output: steering_directions.json -- one entry per model with the direction\n    # (unit-normalized), the chosen layer, and the raw (pre-normalization) norm\n    # and mean per-position activation norm at that layer (both useful later for\n    # picking sensible alpha values relative to the activation scale).\n    # =============================================================================\n\n    from pathlib import Path\n    import json\n    import numpy as np\n\n    GDRIVE_BASE = DATA_ROOT\n    ACTIV_BASE = GDRIVE_BASE / NEW_REV   # CHANGED\n    FILLER_BASE = GDRIVE_BASE / NEW_FIL   # CHANGED\n    EXPORT_DIR = GDRIVE_BASE / "hand_labeling_export"\n    OUT_PATH = EXPORT_DIR / "steering_directions_llama8b_reextract.json"   # CHANGED: new file\n\n    MODELS = ["DeepSeek-R1-Distill-Llama-8B"]   # CHANGED: Llama-8B only\n    CENTER = 30                # same center-token convention used throughout this project\n    PLATEAU_DEPTH_FRACTION = 0.65  # heuristic: comfortably inside the ~32-38%-onset plateau\n\n\n    def peek_n_layers(base_dir, model, key):\n        """Reads just ONE file\'s shape to determine n_layers, without loading\n        everything. Needed before we know which layer to slice down to."""\n        model_dir = base_dir / model\n        if not model_dir.exists():\n            return None\n        for f in sorted(model_dir.glob("*.npz")):\n            with np.load(f) as z:\n                if key in z:\n                    return z[key].shape[1]\n        return None\n\n\n    def load_sliced_windows(base_dir, model, key, layer, center):\n        """Loads each file\'s array, immediately slices down to [:, layer, center, :],\n        and discards the full array before moving to the next file. Peak memory is\n        one file\'s full array at a time (transient), not every file\'s full array\n        held simultaneously -- the previous version\'s np.concatenate(arrays) after\n        the loop kept everything in memory at once, which is what blew up on\n        Qwen-14B (48 layers x 5120 hidden dim -- ~51GB combined across both\n        revision and filler arrays, held simultaneously, well past typical Colab\n        RAM). This version only ever holds the small (n_events_in_file, hidden_dim)\n        slices, which are orders of magnitude smaller."""\n        slices = []\n        model_dir = base_dir / model\n        if not model_dir.exists():\n            return None\n        for f in sorted(model_dir.glob("*.npz")):\n            with np.load(f) as z:\n                if key not in z:\n                    continue\n                arr = z[key]                       # full array for this file, transient\n                sliced = arr[:, layer, center, :].astype(np.float32).copy()\n                slices.append(sliced)\n                del arr                            # explicit, though scope-exit would do this anyway\n        if not slices:\n            return None\n        return np.concatenate(slices, axis=0)      # concatenating small slices is cheap\n\n\n    def extract_direction_for_model(model):\n        n_layers = peek_n_layers(ACTIV_BASE, model, "revision_windows")\n        if n_layers is None:\n            print(f"  {model}: no revision_windows files found -- skipping")\n            return None\n\n        layer = int(round(PLATEAU_DEPTH_FRACTION * (n_layers - 1)))\n        layer = max(0, min(layer, n_layers - 1))\n\n        rev_vecs = load_sliced_windows(ACTIV_BASE, model, "revision_windows", layer, CENTER)\n        fil_vecs = load_sliced_windows(FILLER_BASE, model, "filler_windows", layer, CENTER)\n\n        if rev_vecs is None or fil_vecs is None:\n            print(f"  {model}: missing revision_windows or filler_windows -- skipping")\n            return None\n\n        rev_mean = rev_vecs.mean(axis=0)\n        fil_mean = fil_vecs.mean(axis=0)\n        raw_direction = rev_mean - fil_mean\n        raw_norm = float(np.linalg.norm(raw_direction))\n\n        if raw_norm == 0:\n            print(f"  {model}: degenerate zero-norm direction at layer {layer} -- skipping")\n            return None\n\n        unit_direction = raw_direction / raw_norm\n\n        # mean activation norm at this layer/position -- reference scale for alpha calibration\n        all_vecs = np.concatenate([rev_vecs, fil_vecs], axis=0)\n        mean_activation_norm = float(np.linalg.norm(all_vecs, axis=1).mean())\n\n        return {\n            "model": model,\n            "n_layers": n_layers,\n            "layer": layer,\n            "layer_fraction": layer / (n_layers - 1),\n            "n_revision_events": int(rev_vecs.shape[0]),\n            "n_filler_events": int(fil_vecs.shape[0]),\n            "raw_direction_norm": raw_norm,\n            "mean_activation_norm_at_layer": mean_activation_norm,\n            "unit_direction": unit_direction.tolist(),\n        }\n\n\n    def main():\n        results = {}\n        for model in MODELS:\n            print(f"\\n{model}")\n            r = extract_direction_for_model(model)\n            if r is not None:\n                results[model] = r\n                print(f"  layer={r[\'layer\']}/{r[\'n_layers\']} ({r[\'layer_fraction\']:.0%} depth)  "\n                      f"n_revision={r[\'n_revision_events\']}  n_filler={r[\'n_filler_events\']}")\n                print(f"  raw direction norm={r[\'raw_direction_norm\']:.3f}  "\n                      f"mean activation norm at this layer={r[\'mean_activation_norm_at_layer\']:.3f}")\n                print(f"  (ratio: direction is {r[\'raw_direction_norm\']/r[\'mean_activation_norm_at_layer\']:.1%} "\n                      f"of typical activation magnitude at this layer -- a sanity check, not itself alpha)")\n\n        with open(OUT_PATH, "w") as f:\n            json.dump(results, f)\n        print(f"\\nWrote {len(results)} model directions to {OUT_PATH}")\n\n\n    main()   # CHANGED: called directly (was under if __name__ == "__main__")\n    import numpy as np\n    _old = json.load(open(DATA_ROOT / "hand_labeling_export" / "steering_directions.json"))\n    _old = _old.get("models", _old)\n    _new = json.load(open(DATA_ROOT / "hand_labeling_export" / "steering_directions_llama8b_reextract.json"))\n    o, n = _old[LLAMA], _new[LLAMA]\n    uo, un = np.array(o["unit_direction"]), np.array(n["unit_direction"])\n    print(f"\\n  Llama-8B steering direction, original vs re-extracted windows:")\n    print(f"    layer                {o.get(\'layer\')}  vs  {n[\'layer\']}")\n    print(f"    events (rev/fil)     {o.get(\'n_revision_events\')}/{o.get(\'n_filler_events\')}  vs  "\n          f"{n[\'n_revision_events\']}/{n[\'n_filler_events\']}")\n    print(f"    raw direction norm   {o[\'raw_direction_norm\']:.4f}  vs  {n[\'raw_direction_norm\']:.4f}"\n          f"   (alpha = 1.5 x this: {1.5*o[\'raw_direction_norm\']:.3f} vs {1.5*n[\'raw_direction_norm\']:.3f})")\n    print(f"    cosine(original unit direction, new unit direction) = {float(uo @ un):+.4f}")\n\n\n# #############################################################################\n# STAGE "probe" — notebook 06 Parts A and B, verbatim (Llama-8B, new folders,\n# separate result files). CPU.\n# #############################################################################\nif "probe" in STAGES:\n    # ---- 06, cell 1 (verbatim except where marked) ----\n    # =============================================================================\n    # 06 PART A -- MATCHED-MARKER PROBE (Table 1: matched, null, all CIs)\n    #\n    # For each model: pick the layer with the highest matched accuracy (revision\n    # vs filler windows, centre position = token before the marker), then\n    # bootstrap matched, null (filler vs filler) and their within-replicate\n    # difference, N_BOOT = 2000.\n    #\n    #   * Group-aware CV (StratifiedGroupKFold on original event ids), so a\n    #     resampled duplicate never sits on both sides of a fold.\n    #   * StandardScaler -> PCA(50, fit inside each fold) -> logistic regression.\n    #   * Matched / null point estimates are the mean of N_PT_DRAWS = 30 balanced\n    #     draws.\n    #   * The full per-layer accuracy profile is saved with each model.\n    #\n    # The residual point estimate written here is the UNPAIRED difference\n    # (matched_pt - null_pt). Part B recomputes it paired, which is what Table 1\n    # reports.\n    #\n    # CPU, hours. Resumable: models already in OUTFILE are skipped.\n    # =============================================================================\n\n    from pathlib import Path\n    GDRIVE_BASE = DATA_ROOT\n    assert (GDRIVE_BASE / "activations").exists(),        "activations/ missing -- bad mount"\n    assert (GDRIVE_BASE / "activations_filler").exists(), "fillers missing -- bad mount"\n    print("Drive mounted, data visible.")\n\n    import json, gc\n    import numpy as np\n    from sklearn.linear_model import LogisticRegression\n    from sklearn.preprocessing import StandardScaler\n    from sklearn.decomposition import PCA\n    from sklearn.pipeline import Pipeline\n    from sklearn.model_selection import StratifiedGroupKFold\n    import warnings\n    warnings.filterwarnings("ignore")\n\n    ACTIV_BASE  = GDRIVE_BASE / NEW_REV   # CHANGED\n    FILLER_BASE = GDRIVE_BASE / NEW_FIL   # CHANGED\n    RESULTS_DIR = GDRIVE_BASE / "results_v3"\n    RESULTS_DIR.mkdir(parents=True, exist_ok=True)\n\n    MODELS = ["DeepSeek-R1-Distill-Llama-8B"]   # CHANGED: Llama-8B only\n\n    CENTER       = 30\n    SEED         = 42\n    N_PCA        = 50          # pre-committed headline dimensionality\n    MAX_ITER     = 2000\n    N_BOOT       = 2000\n    N_PT_DRAWS   = 30          # averaged point-estimate draws\n    FLAT_WINDOW  = 0.02        # layers within this of peak are "flat with it"\n\n    OUTFILE = RESULTS_DIR / "task1_residual_cis_nboot2000_v3_llama8b_reextract.json"   # CHANGED\n\n    # ---- 06, cell 2 (verbatim except where marked) ----\n    def load_rev(m):\n        rev = []\n        for p in sorted((ACTIV_BASE / m).glob("*.npz")):\n            rw = np.load(p).get("revision_windows")\n            if rw is not None:\n                rev.extend(rw[i] for i in range(rw.shape[0]))\n        return rev\n\n    def load_fil(m):\n        fil = []\n        for p in sorted((FILLER_BASE / m).glob("*.npz")):\n            w = np.load(p).get("filler_windows")\n            if w is not None:\n                fil.extend(w[i] for i in range(w.shape[0]))\n        return fil\n\n\n    # -----------------------------------------------------------------------\n    # cv_accuracy threads original-event-id groups through every\n    # subsampling step and uses StratifiedGroupKFold. Every array of features\n    # passed in (Xp, Xn) must be accompanied by a same-length array of original\n    # event IDs (gp, gn) so duplicates introduced by bootstrap resampling never\n    # get split across train/test.\n    # -----------------------------------------------------------------------\n    def cv_accuracy(Xp, Xn, gp, gn, seed):\n        """Balanced 5-fold, group-aware CV accuracy. PCA fit inside each fold."""\n        n = min(len(Xp), len(Xn))\n        if n < 20:\n            return 0.5\n        rng = np.random.RandomState(seed)\n        idx_p = rng.choice(len(Xp), n, False)\n        idx_n = rng.choice(len(Xn), n, False)\n        X = np.vstack([Xp[idx_p], Xn[idx_n]]).astype(np.float32)\n        X = np.nan_to_num(X, nan=0., posinf=0., neginf=0.)\n        y = np.array([1]*n + [0]*n)\n        g = np.concatenate([gp[idx_p], gn[idx_n]])\n\n        ncomp = min(N_PCA, len(y) - 1)\n        pipe = Pipeline([\n            ("sc",  StandardScaler()),\n            ("pca", PCA(n_components=ncomp, random_state=seed)),\n            ("clf", LogisticRegression(max_iter=MAX_ITER, random_state=seed)),\n        ])\n        cv = StratifiedGroupKFold(5, shuffle=True, random_state=seed)\n        accs = []\n        for tr, te in cv.split(X, y, groups=g):\n            pipe.fit(X[tr], y[tr])\n            accs.append((pipe.predict(X[te]) == y[te]).mean())\n        return float(np.mean(accs))\n\n\n    def averaged_point_estimate(Xp, Xn, gp, gn, base_seed, n_draws=N_PT_DRAWS):\n        """Point estimate = mean cv_accuracy over n_draws independent\n        balanced subsample draws, so it isn\'t hostage to one lucky split."""\n        vals = [cv_accuracy(Xp, Xn, gp, gn, base_seed + 10_000 + d) for d in range(n_draws)]\n        return float(np.mean(vals)), vals\n\n\n    def peak_layer(rev, fil, nl):\n        """Returns the peak layer and the full per-layer accuracy profile."""\n        profile = []\n        best_l, best_a = 0, 0.0\n        rev_ids = np.arange(len(rev))\n        fil_ids = np.arange(len(fil)) + 10**7   # disjoint id space from revisions\n        for l in range(nl):\n            Xp = np.array([w[l, CENTER] for w in rev], np.float32)\n            Xn = np.array([w[l, CENTER] for w in fil], np.float32)\n            a = cv_accuracy(Xp, Xn, rev_ids, fil_ids, SEED)\n            profile.append(a)\n            if a > best_a:\n                best_a, best_l = a, l\n        near_peak = [l for l, acc in enumerate(profile) if best_a - acc < FLAT_WINDOW]\n        is_flat = len(near_peak) > 3\n        return best_l, best_a, profile, near_peak, is_flat\n\n\n    def bootstrap_all(rev, fil, L):\n        """\n        Returns point estimates (averaged over draws) and percentile CIs for\n        matched, null, and residual. Bootstrap resamples EVENTS with replacement\n        and REFITS both probes each iteration; original event IDs are carried\n        through the resample step so cv_accuracy\'s group-aware split\n        can prevent the same event landing on both sides of a fold.\n        """\n        Xr = np.array([w[L, CENTER] for w in rev], dtype=np.float32)\n        Xf = np.array([w[L, CENTER] for w in fil], dtype=np.float32)\n        gid_r = np.arange(len(Xr))\n        gid_f = np.arange(len(Xf)) + 10**7\n\n        # ---- point estimates (averaged over N_PT_DRAWS balanced draws) ----\n        matched_pt, matched_draws = averaged_point_estimate(Xr, Xf, gid_r, gid_f, SEED)\n\n        permf = np.random.RandomState(SEED).permutation(len(Xf))\n        hf    = len(Xf) // 2\n        Xf_a, Xf_b_half = Xf[permf[:hf]], Xf[permf[hf:2*hf]]\n        gf_a, gf_b_half = gid_f[permf[:hf]], gid_f[permf[hf:2*hf]]\n        # null halves are disjoint filler subsets -> give them disjoint synthetic\n        # group ids too, since they\'re different physical events by construction\n        null_pt, null_draws = averaged_point_estimate(Xf_a, Xf_b_half, gf_a, gf_b_half, SEED)\n\n        resid_pt = matched_pt - null_pt\n\n        # ---- bootstrap ----\n        rng = np.random.RandomState(SEED)\n        matched_b, null_b, resid_b = [], [], []\n        for b in range(N_BOOT):\n            ir  = rng.choice(len(Xr), len(Xr), replace=True)\n            iff = rng.choice(len(Xf), len(Xf), replace=True)\n            Xr_b, gr_b = Xr[ir], gid_r[ir]\n            Xf_b, gf_b = Xf[iff], gid_f[iff]\n\n            m_b = cv_accuracy(Xr_b, Xf_b, gr_b, gf_b, SEED + b)              # refit, group-aware\n\n            pf  = np.random.RandomState(SEED + b).permutation(len(Xf_b))\n            h   = len(Xf_b) // 2\n            n_b = cv_accuracy(Xf_b[pf[:h]], Xf_b[pf[h:2*h]],\n                               gf_b[pf[:h]], gf_b[pf[h:2*h]], SEED + b)      # refit, group-aware\n\n            matched_b.append(m_b)\n            null_b.append(n_b)\n            resid_b.append(m_b - n_b)\n\n            if (b + 1) % 250 == 0:\n                print(f"      boot {b+1}/{N_BOOT}")\n\n        def ci(arr):\n            lo, hi = np.percentile(arr, [2.5, 97.5])\n            return float(lo), float(hi)\n\n        m_lo, m_hi = ci(matched_b)\n        n_lo, n_hi = ci(null_b)\n        r_lo, r_hi = ci(resid_b)\n\n        return {\n            "matched":      matched_pt, "matched_ci":  [m_lo, m_hi],\n            "null_fil":     null_pt,    "null_ci":     [n_lo, n_hi],\n            "residual":     resid_pt,   "residual_ci": [r_lo, r_hi],\n            "excludes_zero":        bool(r_lo > 0),\n            "null_brackets_chance": bool(n_lo <= 0.50 <= n_hi),\n            "intervals_disjoint":   bool(m_lo > n_hi),\n            # Acceptance-criterion helper: does the point estimate land\n            # comfortably inside its own bootstrap interval, or hug an edge?\n            "matched_pt_ok": bool(m_lo < matched_pt < m_hi),\n            "null_pt_ok":    bool(n_lo < null_pt < n_hi),\n            "n_boot": N_BOOT,\n            "n_pt_draws": N_PT_DRAWS,\n        }\n\n    # ---- 06, cell 3 (verbatim except where marked) ----\n    # ---- resume support -------------------------------------------------------\n    results = {}\n    if OUTFILE.exists():\n        results = json.load(open(OUTFILE))\n        print(f"Resuming -- already done: {list(results.keys())}")\n\n    # ---- 06, cell 4 (verbatim except where marked) ----\n    for m in MODELS:\n        if m in results:\n            print(f"  {m}: already done, skipping")\n            continue\n\n        print(f"\\n{\'=\'*60}\\n{m}\\n{\'=\'*60}")\n        rev = load_rev(m)\n        fil = load_fil(m)\n        nl  = rev[0].shape[0]\n        print(f"  revisions={len(rev)}  fillers={len(fil)}")\n\n        L, a, profile, near_peak, is_flat = peak_layer(rev, fil, nl)\n        print(f"  peak layer = {L}/{nl}  (matched acc={a:.3f})")\n        print(f"  layers within {FLAT_WINDOW} of peak: {near_peak}")\n        print(f"  {\'FLAT PROFILE -- argmax is likely not a real peak\' if is_flat else \'looks like a genuine peak\'}")\n\n        print(f"  bootstrapping (N_BOOT={N_BOOT}, group-aware CV, "\n              f"point estimate averaged over {N_PT_DRAWS} draws)...")\n        r = bootstrap_all(rev, fil, L)\n\n        print(f"    matched  = {r[\'matched\']:.3f}  "\n              f"[{r[\'matched_ci\'][0]:.3f}, {r[\'matched_ci\'][1]:.3f}]  pt_inside_ci={r[\'matched_pt_ok\']}")\n        print(f"    null-fil = {r[\'null_fil\']:.3f}  "\n              f"[{r[\'null_ci\'][0]:.3f}, {r[\'null_ci\'][1]:.3f}]"\n              f"   brackets 0.50: {r[\'null_brackets_chance\']}  pt_inside_ci={r[\'null_pt_ok\']}")\n        print(f"    RESIDUAL = {r[\'residual\']:+.3f}  "\n              f"[{r[\'residual_ci\'][0]:+.3f}, {r[\'residual_ci\'][1]:+.3f}]"\n              f"   excludes 0: {r[\'excludes_zero\']}")\n        print(f"    matched/null intervals disjoint: {r[\'intervals_disjoint\']}")\n\n        results[m] = {"peak_layer": L, "layer_profile": profile,\n                      "near_peak_layers": near_peak, "flat_profile": is_flat,\n                      "n_rev": len(rev), "n_fil": len(fil), **r}\n        json.dump(results, open(OUTFILE, "w"), indent=2)\n        del rev, fil\n        gc.collect()\n\n    # ---- 06, cell 5 (verbatim except where marked) ----\n    # ---- SUMMARY --------------------------------------------------------------\n    print("\\n" + "#"*78)\n    print(f"#  MATCHED-MARKER PROBE (N_BOOT={N_BOOT}, group-aware CV, averaged point estimate)")\n    print("#"*78)\n    print(f"\\n  {\'Model\':<16} {\'matched [95% CI]\':>24} {\'null [95% CI]\':>24} "\n          f"{\'residual [95% CI]\':>26}")\n    print("  " + "-"*92)\n    for m in MODELS:\n        if m not in results:\n            continue\n        r = results[m]\n        short = m.replace("DeepSeek-R1-Distill-", "R1-")\n        print(f"  {short:<16} "\n              f"{r[\'matched\']:.3f} [{r[\'matched_ci\'][0]:.3f},{r[\'matched_ci\'][1]:.3f}]".rjust(24)\n              + "  " +\n              f"{r[\'null_fil\']:.3f} [{r[\'null_ci\'][0]:.3f},{r[\'null_ci\'][1]:.3f}]".rjust(22)\n              + "  " +\n              f"{r[\'residual\']:+.3f} [{r[\'residual_ci\'][0]:+.3f},{r[\'residual_ci\'][1]:+.3f}]".rjust(24))\n\n    print("\\n  ACCEPTANCE CRITERIA")\n    print("  " + "-"*76)\n    for m in MODELS:\n        if m not in results:\n            continue\n        r = results[m]\n        short = m.replace("DeepSeek-R1-Distill-", "R1-")\n        print(f"    {short:<16} pt-in-CI(matched/null): "\n              f"{str(r[\'matched_pt_ok\']):>5}/{str(r[\'null_pt_ok\']):>5}   "\n              f"residual excl. 0: {str(r[\'excludes_zero\']):>5}   "\n              f"null brackets .50: {str(r[\'null_brackets_chance\']):>5}   "\n              f"flat peak profile: {str(r[\'flat_profile\']):>5}")\n\n    n_pass    = sum(results[m]["excludes_zero"] for m in results)\n    n_null_ok = sum(results[m]["null_brackets_chance"] for m in results)\n    n_pt_ok   = sum(results[m]["matched_pt_ok"] and results[m]["null_pt_ok"] for m in results)\n    print(f"\\n  {n_pass}/{len(results)} residual CIs exclude zero.")\n    print(f"  {n_null_ok}/{len(results)} null CIs bracket chance (0.50) as they should.")\n    print(f"  {n_pt_ok}/{len(results)} models have BOTH point estimates comfortably inside their CIs.")\n    if n_pass == len(results) and n_null_ok == len(results) and n_pt_ok == len(results):\n        print("  >>> All acceptance criteria met (duplicate-leakage-free).")\n    else:\n        print("  >>> One or more acceptance criteria failed -- see per-model detail above "\n              "before writing anything up.")\n\n    # ---- 06, cell 6 (verbatim except where marked) ----\n    # =============================================================================\n    # 06 PART B -- PAIRED RESIDUAL POINT ESTIMATE (Table 1: residual column)\n    #\n    # Part A\'s residual point estimate is matched_pt - null_pt, two separately\n    # averaged marginals, while its CI comes from within-replicate differences.\n    # They describe different quantities, and for Qwen-7B the point estimate\n    # fell outside its own CI. This recomputes the point estimate the way the\n    # bootstrap pairs it: one balanced filler subsample per draw, used for both\n    # the matched negative class and the null split, differenced within the draw,\n    # averaged over N_PT_DRAWS = 100 draws, at Part A\'s saved peak layer.\n    #\n    # matched, null and all three CIs are carried over from Part A unchanged.\n    # Writes results_v3/task1_residual_pointfix.json (the file Table 1 cites:\n    # column `residual_paired`).\n    #\n    # CPU, minutes per model.\n    # =============================================================================\n\n    from pathlib import Path\n    import json, gc\n    import numpy as np\n    from sklearn.linear_model import LogisticRegression\n    from sklearn.preprocessing import StandardScaler\n    from sklearn.decomposition import PCA\n    from sklearn.pipeline import Pipeline\n    from sklearn.model_selection import StratifiedGroupKFold\n    import warnings\n    warnings.filterwarnings("ignore")\n\n    GDRIVE_BASE = DATA_ROOT\n    ACTIV_BASE  = GDRIVE_BASE / NEW_REV   # CHANGED\n    FILLER_BASE = GDRIVE_BASE / NEW_FIL   # CHANGED\n\n    # Part A\'s results file\n    V3_RESULTS_PATH = GDRIVE_BASE / "results_v3" / "task1_residual_cis_nboot2000_v3_llama8b_reextract.json"   # CHANGED\n    OUT_PATH        = GDRIVE_BASE / "results_v3" / "task1_residual_pointfix_llama8b_reextract.json"   # CHANGED\n\n    MODELS = ["DeepSeek-R1-Distill-Llama-8B"]   # CHANGED: Llama-8B only\n\n    CENTER     = 30\n    SEED       = 42\n    N_PCA      = 50     # must match Part A\n    MAX_ITER   = 2000   # must match Part A\n    N_PT_DRAWS = 100    # paired draws (Part A used 30 for its unpaired marginals)\n\n\n    def load_rev(m):\n        out = []\n        for p in sorted((ACTIV_BASE / m).glob("*.npz")):\n            with np.load(p) as z:\n                rw = z.get("revision_windows")\n                if rw is not None:\n                    out.extend(rw[i] for i in range(rw.shape[0]))\n        return out\n\n\n    def load_fil(m):\n        out = []\n        for p in sorted((FILLER_BASE / m).glob("*.npz")):\n            with np.load(p) as z:\n                w = z.get("filler_windows")\n                if w is not None:\n                    out.extend(w[i] for i in range(w.shape[0]))\n        return out\n\n\n    def cv_accuracy(Xp, Xn, gp, gn, seed):\n        """Identical to Part A\'s: balanced, group-aware, PCA fit inside each fold."""\n        n = min(len(Xp), len(Xn))\n        if n < 20:\n            return 0.5\n        rng = np.random.RandomState(seed)\n        ip = rng.choice(len(Xp), n, False)\n        inn = rng.choice(len(Xn), n, False)\n        X = np.vstack([Xp[ip], Xn[inn]]).astype(np.float32)\n        X = np.nan_to_num(X, nan=0., posinf=0., neginf=0.)\n        y = np.array([1]*n + [0]*n)\n        g = np.concatenate([gp[ip], gn[inn]])\n        pipe = Pipeline([\n            ("sc",  StandardScaler()),\n            ("pca", PCA(n_components=min(N_PCA, len(y) - 1), random_state=seed)),\n            ("clf", LogisticRegression(max_iter=MAX_ITER, random_state=seed)),\n        ])\n        cv = StratifiedGroupKFold(5, shuffle=True, random_state=seed)\n        accs = []\n        for tr, te in cv.split(X, y, groups=g):\n            pipe.fit(X[tr], y[tr])\n            accs.append((pipe.predict(X[te]) == y[te]).mean())\n        return float(np.mean(accs))\n\n\n    def paired_residual(Xr, Xf, gid_r, gid_f, base_seed, n_draws=N_PT_DRAWS):\n        """One balanced filler subsample per draw, used for BOTH the matched\n        negative class and the null split -- mirroring what each bootstrap\n        replicate does, so the point estimate and the CI describe the same\n        quantity."""\n        vals = []\n        for d in range(n_draws):\n            seed = base_seed + 10_000 + d\n            rng = np.random.RandomState(seed)\n            n = min(len(Xr), len(Xf))\n            ir = rng.choice(len(Xr), n, False)\n            iff = rng.choice(len(Xf), n, False)\n            Xr_d, gr_d = Xr[ir], gid_r[ir]\n            Xf_d, gf_d = Xf[iff], gid_f[iff]\n\n            m = cv_accuracy(Xr_d, Xf_d, gr_d, gf_d, seed)\n\n            pf = np.random.RandomState(seed).permutation(len(Xf_d))\n            h = len(Xf_d) // 2\n            n_ = cv_accuracy(Xf_d[pf[:h]], Xf_d[pf[h:2*h]],\n                              gf_d[pf[:h]], gf_d[pf[h:2*h]], seed)\n            vals.append(m - n_)\n        return float(np.mean(vals)), vals\n\n\n    def main():\n        assert V3_RESULTS_PATH.exists(), (\n            f"{V3_RESULTS_PATH} not found -- point this at your v3 results JSON.")\n        with open(V3_RESULTS_PATH) as f:\n            v3 = json.load(f)\n        print(f"Loaded v3 results for: {list(v3.keys())}\\n")\n\n        out = {}\n        for m in MODELS:\n            if m not in v3:\n                print(f"{m}: not in v3 results, skipping")\n                continue\n            r = v3[m]\n            layer = r["peak_layer"]\n            old_resid = r["residual"]\n            lo, hi = r["residual_ci"]\n\n            print(f"{\'=\'*66}\\n{m}\\n{\'=\'*66}")\n            print(f"  peak layer {layer} (reused from v3 -- no layer sweep)")\n            print(f"  v3 residual {old_resid:+.4f}  CI [{lo:+.4f}, {hi:+.4f}]  "\n                  f"inside CI: {lo < old_resid < hi}")\n\n            rev, fil = load_rev(m), load_fil(m)\n            Xr = np.array([w[layer, CENTER] for w in rev], dtype=np.float32)\n            Xf = np.array([w[layer, CENTER] for w in fil], dtype=np.float32)\n            gid_r = np.arange(len(Xr))\n            gid_f = np.arange(len(Xf)) + 10**7\n            print(f"  n_rev={len(Xr)}  n_fil={len(Xf)}  -- computing {N_PT_DRAWS} paired draws...")\n\n            new_resid, draws = paired_residual(Xr, Xf, gid_r, gid_f, SEED)\n            inside = lo < new_resid < hi\n            print(f"  NEW residual {new_resid:+.4f}  (draw sd {np.std(draws):.4f})")\n            print(f"  inside its own CI: {inside}   change {new_resid - old_resid:+.4f}")\n\n            out[m] = {\n                "peak_layer": layer,\n                "residual_v3_unpaired": old_resid,\n                "residual_paired": new_resid,\n                "residual_ci": [lo, hi],\n                "inside_ci_before": bool(lo < old_resid < hi),\n                "inside_ci_after": bool(inside),\n                "n_pt_draws": N_PT_DRAWS,\n                "draw_sd": float(np.std(draws)),\n                # unchanged, carried through for a complete table\n                "matched": r["matched"], "matched_ci": r["matched_ci"],\n                "null_fil": r["null_fil"], "null_ci": r["null_ci"],\n            }\n            del rev, fil, Xr, Xf\n            gc.collect()\n\n        print(f"\\n{\'#\'*66}\\n# CORRECTED RESIDUAL TABLE\\n{\'#\'*66}")\n        print(f"{\'Model\':<32} {\'old\':>8} {\'new\':>8}  {\'CI\':>22}  in CI")\n        all_ok = True\n        for m, r in out.items():\n            lo, hi = r["residual_ci"]\n            ok = r["inside_ci_after"]\n            all_ok &= ok\n            print(f"{m:<32} {r[\'residual_v3_unpaired\']:+.4f} {r[\'residual_paired\']:+.4f}  "\n                  f"[{lo:+.4f}, {hi:+.4f}]  {ok}")\n        print(f"\\nAll point estimates inside their own CIs: {all_ok}")\n        if not all_ok:\n            print("If any remain outside, that is genuine skew rather than the pairing")\n            print("mismatch -- worth understanding before publishing, not patching over.")\n\n        with open(OUT_PATH, "w") as f:\n            json.dump(out, f, indent=2)\n        print(f"\\nWrote {OUT_PATH}")\n        print("\\nNOTE: matched, null, and ALL THREE CIs are unchanged from v3. Only the")\n        print("residual POINT ESTIMATE is recomputed. The CIs were already paired")\n        print("(bootstrap replicates difference within-replicate), so they were always")\n        print("correct -- it was the point estimate that was inconsistent with them.")\n\n\n    if __name__ == "__main__":\n        main()\n'

SRC['necessity'] = '# =============================================================================\n# 09 — NECESSITY: LEXICAL SUPPRESSION AND ACTIVATION STEERING\n#\n# Run in Colab (GPU for the two generation stages). Set STAGE below, run the\n# whole file, read the output, then move to the next stage:\n#     select -> lexical -> steering -> analyze\n#\n# The paper\'s steering numbers are STEERING_CORRECTED in `analyze`: the three\n# Qwen models from STAGE = "steering" (published directions), and Llama-8B from\n# a second STAGE = "steering" run with LLAMA_DIRECTION = "reextract", whose\n# direction is rebuilt from the re-extracted Llama-8B windows\n# (pipeline/11_reextract_llama8b.py, stages revision, filler, direction).\n# pipeline/RUN_llama8b_direction_all.py runs that second part in one go.\n#\n# SAMPLE = "original" (default): the 83 revision + 80 filler events of the\n#   first version of the paper (counterfactual_pilot_events.json and\n#   filler_control_pilot_events.json), re-run with clean prefixes.\n# SAMPLE = "redraw": a new uniform draw of up to N_PAIRS matched pairs.\n#\n# Outputs go to hand_labeling_export/redraw_2026_10/[original_rerun_clean_prefix/];\n# nothing published is overwritten. Stages resume where they stopped.\n# =============================================================================\n# =============================================================================\n# NECESSITY RE-RUN / REDRAW\n#\n# Oct 27: SAMPLE = "original" (default) re-runs the PUBLISHED 83/80 events\n# with byte-level-BPE-free prefixes (all 39 old Llama-8B prefixes were in Ġ/Ċ\n# characters), the two never-generated lexical events, and event-keyed resume.\n# Output: hand_labeling_export/redraw_2026_10/original_rerun_clean_prefix/\n# SAMPLE = "redraw" is the 160+160 uniform redraw described below.\n#\n# Replaces the inherited 83/80 sample for the revision. The old results are\n# NEVER read for writing and NEVER overwritten: everything goes to\n#   hand_labeling_export/redraw_2026_10/\n#\n# Run one stage at a time, in order:\n#   STAGE = "select"     CPU, minutes.  Builds the event files. Read its report.\n#   STAGE = "lexical"    GPU.  Lexical suppression rollouts, both arms.\n#   STAGE = "steering"   GPU.  Activation-steering rollouts, both arms.\n#   STAGE = "analyze"    CPU, minutes.  All reported outputs, old beside new.\n#\n# What is different from the 83/80 pipeline, and why — every item is logged\n# in manifest.json:\n#   1. Eligibility uses the CORRECTED parser (extract_answer_new +\n#      normalise_answer + load_gt(use_repaired)), not the saved `correct` flag.\n#   2. The revision arm is drawn uniformly from all GPT-4o-verified revisions\n#      in eligible traces — no human-label gate. The filler arm is drawn from\n#      GPT-4o-confirmed fillers in eligible traces, 1:1 on (model, marker),\n#      with the marker normalised exactly as the filler-arm selection did\n#      (superseded/necessity_lexical_filler_arm.ipynb).\n#   3. Every offset is VERIFIED: the marker text must sit at char_start in the\n#      trace. Failures are dropped and counted, never guessed.\n#   4. Resume is keyed on the EVENT — (arm, model, problem_id, char_start) —\n#      not (problem_id, model). The old key silently dropped the second event\n#      of any problem with two events on a resumed run; the steering generator\n#      (superseded/necessity_steering_both_arms.ipynb) had the same key.\n#   5. PREFIX RESTORATION. The old prefixes were full_response[:cs] passed to\n#      the tokenizer raw. If a trace was stored in byte-level-BPE character\n#      space (literal Ġ for space, Ċ for newline), the model was conditioned\n#      on text it never produced. Here the slice is taken FIRST, then decoded,\n#      so offsets stay valid. The path taken for each event is recorded, and\n#      the select stage reports how many OLD prefixes were affected.\n#   6. Seeds fixed and logged. Wall-clock per stage and per event, GPU name,\n#      and package versions are written to manifest.json, so the compute\n#      section can be measured rather than reconstructed.\n#\n# Production code is EMBEDDED verbatim (see "EMBEDDED PRODUCTION CODE"\n# below): generators, leak filter, answer extractor, ground-truth loader,\n# necessity scorer and marker normaliser. No code is read from Drive; Drive\n# holds data only.\n# =============================================================================\n\nSTAGE         = "select"          # select | lexical | steering | analyze\nLLAMA_DIRECTION = "original"      # steering stage only:\n                                  # "original":  directions from steering_directions.json\n                                  #   (Llama-8B\'s was built from the original Llama-8B\n                                  #   windows, which could not be reproduced)\n                                  # "reextract": Llama-8B ONLY, direction rebuilt from the\n                                  #   re-extracted windows (11_reextract_llama8b.py, stage\n                                  #   "direction"); same seeds and strength multiplier;\n                                  #   separate rollout files\nSAMPLE        = "original"        # "original": re-run the published 83/80\n                                  #   events with clean prefixes (Oct 27)\n                                  # "redraw":   new 160+160 uniform draw\nRERUN_MODELS  = None              # None = all four models. To re-run only\n                                  # the model whose prefixes were corrupted:\n                                  # ["DeepSeek-R1-Distill-Llama-8B"]\nN_PAIRS       = 160               # revision/filler pairs to draw (redraw only)\nINTERVENTIONS = ("lexical", "steering")\nSEEDS = {"select": 20261020, "match": 20261021,\n         # rollout seed = base + r, as in the published runs:\n         #   lexical  1000 + r  (superseded/necessity_lexical_revision_arm.py,\n         #                       necessity_lexical_filler_arm.ipynb)\n         #   steering 4000 + r  (calling loop in necessity_steering_both_arms.ipynb)\n         "rollout_base": {"lexical": 1000, "steering": 4000,\n                          "steering_llama8b_reextract": 4000}}\nMODELS = ["DeepSeek-R1-Distill-Llama-8B", "DeepSeek-R1-Distill-Qwen-1.5B",\n          "DeepSeek-R1-Distill-Qwen-7B", "DeepSeek-R1-Distill-Qwen-14B"]\nN_BOOT = 2000\n\nimport ast, hashlib, inspect, json, math, os, random, re, sys, time, types\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom collections import Counter, defaultdict\n\nimport numpy as np\n\nBASE    = Path(os.environ.get("REVISION_DATA_ROOT",\n                              os.environ.get("P2_BASE", "/content/gdrive/MyDrive/llm_planning_study")))\nif not BASE.exists():\n    try:\n        from google.colab import drive; drive.mount("/content/gdrive")\n    except Exception as e:\n        print(f"mount: {e}")\nEXPORT  = BASE / "hand_labeling_export"\nLABELS  = BASE / "labels"\nREJECTS = BASE / "rejects"\nTRACES  = BASE / "traces"\nOUT_DIR = EXPORT / "redraw_2026_10"\nif SAMPLE == "original":\n    OUT_DIR = OUT_DIR / "original_rerun_clean_prefix"\nOUT_DIR.mkdir(parents=True, exist_ok=True)\nif RERUN_MODELS: MODELS = [m for m in MODELS if m in RERUN_MODELS]\n\nEV_REV   = OUT_DIR / "redraw_revision_events.json"\nEV_FIL   = OUT_DIR / "redraw_filler_events.json"\nROLL     = {("lexical", arm): OUT_DIR / f"redraw_lexical_{arm}_rollouts.json"\n            for arm in ("revision", "filler")}\nROLL.update({("steering", arm): OUT_DIR / f"redraw_steering_{arm}_rollouts_seed4000.json"\n             for arm in ("revision", "filler")})\n# the first steering re-run (Nov 1) used 1000 + r by mistake; kept, and reported\n# by `analyze` as a second, independent seed set\nROLL.update({("steering_seed1000", arm): OUT_DIR / f"redraw_steering_{arm}_rollouts.json"\n             for arm in ("revision", "filler")})\n# Llama-8B steering with the direction rebuilt from the re-extracted windows\nROLL.update({("steering_llama8b_reextract", arm):\n             OUT_DIR / f"redraw_steering_{arm}_rollouts_seed4000_llama8b_reextract.json"\n             for arm in ("revision", "filler")})\n# what `analyze` scores as the corrected steering result: Qwen models from the\n# seed-4000 files + Llama-8B from the re-extract files (merged copy, rebuilt\n# by every `analyze`)\nROLL.update({("steering_corrected", arm):\n             OUT_DIR / f"redraw_steering_{arm}_rollouts_seed4000_CORRECTED_merged.json"\n             for arm in ("revision", "filler")})\nLLAMA = "DeepSeek-R1-Distill-Llama-8B"\nMANIFEST = OUT_DIR / "manifest.json"\nRESULTS  = OUT_DIR / "redraw_results.json"\n\nOLD = {"lexical":  {"n": "81/80", "rev": 0.194, "fil": 0.095, "diff": 0.099,\n                    "p": 0.0036, "ci": (0.043, 0.159), "rep": 0.112},\n       "steering": {"n": "83/80", "rev": 0.276, "fil": 0.175, "diff": 0.101,\n                    "p": 0.022, "ci": (0.022, 0.190), "rep": 0.118}}\n\ndef hdr(t): print(f"\\n{\'=\'*78}\\n{t}\\n{\'=\'*78}", flush=True)\ndef rjson(p, default=None):\n    try: return json.load(open(p))\n    except Exception: return default\ndef wjson(obj, p):\n    tmp = Path(str(p) + ".tmp")\n    json.dump(obj, open(tmp, "w"), indent=1, default=str)\n    os.replace(tmp, p)\ndef now(): return datetime.now(timezone.utc).isoformat()\n\n\n# ---------------------------------------------------------------------------\n# manifest — one record per stage run\n# ---------------------------------------------------------------------------\ndef env_info():\n    info = {"python": sys.version.split()[0]}\n    for mod in ("torch", "transformers", "numpy", "scipy", "sklearn"):\n        try:\n            m = __import__(mod); info[mod] = getattr(m, "__version__", "?")\n        except Exception:\n            info[mod] = None\n    try:\n        import torch\n        info["gpu"] = (torch.cuda.get_device_name(0)\n                       if torch.cuda.is_available() else "none")\n        info["cuda"] = torch.version.cuda\n    except Exception:\n        info["gpu"] = None\n    return info\n\ndef manifest_add(rec):\n    m = rjson(MANIFEST, {"stages": []})\n    m["stages"].append(rec)\n    wjson(m, MANIFEST)\n\n\n# ---------------------------------------------------------------------------\n# EMBEDDED PRODUCTION CODE (Oct 29). Nothing used to GENERATE or SCORE\n# rollouts is searched for on Drive any more: several debugging versions of\n# the necessity notebook exist there, and the first lexical re-run picked the\n# 27-phrase pilot. These are verbatim copies:\n#   lexical  : superseded/necessity_lexical_revision_arm.py (38 phrases,\n#              boundary prefixes; same list as the filler-arm notebook)\n#   steering : the steering generator used for the published runs\n#              (generate_with_steering, alpha table CHOSEN_ALPHA_MULTIPLIER)\n#   leak     : is_leaked + EXPLICITLY_BANNED from\n#              superseded/necessity_steering_both_arms.ipynb (the published\n#              leak-filter sensitivity)\n#   extractor: boxed_spans / normalise_answer / extract_answer_new / STOPWORDS\n#              as used for the paper\'s corrected necessity numbers (identical\n#              to superseded/necessity_verification_and_leak_audit.ipynb §1)\n#   scorer   : load_gt / necessity_scores, verbatim from that notebook\'s §1\n# ---------------------------------------------------------------------------\nREFS = {\'lexical\': {\'N_ROLLOUTS\': \'N_ROLLOUTS = 8\\n\', \'ROLLOUT_MAX_NEW_TOKENS\': \'ROLLOUT_MAX_NEW_TOKENS = 2048   # smaller than the original 8192 -- continuing\\n\', \'SAMPLE_TEMPERATURE\': \'SAMPLE_TEMPERATURE = 0.6\\n\', \'SAMPLE_TOP_P\': \'SAMPLE_TOP_P = 0.95\\n\', \'build_prompt\': \'def build_prompt(problem: dict, tokenizer, model_name: str) -> str:\\n    is_reasoning = any(tag in model_name for tag in ["R1", "QwQ"])\\n\\n    if problem["difficulty"] == "hard":\\n        instruction = (\\n            "Solve the following competition mathematics problem carefully. "\\n            "Show your reasoning step by step and verify your answer."\\n        )\\n    else:\\n        instruction = (\\n            "Solve the following mathematics competition problem. "\\n            "Show your working step by step."\\n        )\\n\\n    if is_reasoning:\\n        messages = [{"role": "user",\\n                     "content": f"{instruction}\\\\n\\\\nProblem: {problem[\\\'problem\\\']}"}]\\n    else:\\n        messages = [\\n            {"role": "system",\\n             "content": "You are an expert mathematician. Solve problems with "\\n                        "clear step-by-step reasoning."},\\n            {"role": "user",\\n             "content": f"{instruction}\\\\n\\\\nProblem: {problem[\\\'problem\\\']}"}\\n        ]\\n\\n    return tokenizer.apply_chat_template(\\n        messages, tokenize=False, add_generation_prompt=True\\n    )\\n\', \'SUPPRESSED_PHRASES\': \'SUPPRESSED_PHRASES = [\\n    "wait", "Wait", "actually", "Actually", "let me reconsider",\\n    "that\\\'s wrong", "that is wrong", "i made an error", "I made an error",\\n    "let me try again", "this doesn\\\'t work", "this does not work",\\n    "i need to reconsider", "I need to reconsider", "hmm", "Hmm",\\n    "that\\\'s not right", "that is not right", "let me rethink",\\n    "on second thought", "let me go back", "wait, let me", "Wait, let me",\\n    "actually, let me", "Actually, let me", "let me recheck", "let me re-check",\\n    # Added after auditing suppression leaks -- these are confirmed real\\n    # matched_text values seen in this project\\\'s actual labels/*.json data\\n    # (e.g. during the type_hint vs verdict investigation) that REVISION_RE\\n    # from Task_1_Data_Pipeline.ipynb did NOT cover -- that regex is\\n    # apparently incomplete relative to whatever actually generated the real\\n    # marker detections. If more gaps turn up via audit_suppression_leaks.py,\\n    # add them here too rather than treating this list as final.\\n    "alternatively", "Alternatively", "I made a mistake", "i made a mistake",\\n    "I think I made a mistake", "let me double check", "let me double-check",\\n    "Let me double check", "Let me double-check",\\n    # Added after reading real rollout transcripts (Step 2.5) -- "hold on"\\n    # leaked repeatedly and was never on any version of this list.\\n    "hold on", "Hold on",\\n]\\n\', \'build_bad_words_ids\': \'def build_bad_words_ids(tokenizer):\\n    """\\n    Builds token-id sequences to ban via generate()\\\'s bad_words_ids. Tries each\\n    phrase with several boundary-context prefixes, since byte-level BPE\\n    tokenizers can merge preceding whitespace/punctuation into the SAME token\\n    as the following word -- e.g. "\\\\\\\\n\\\\\\\\nAlternatively" may be encoded as a\\n    compound token distinct from both "Alternatively" and " Alternatively".\\n    Missing a merge pattern means the ban silently never engages for that\\n    specific boundary -- this cannot be assumed complete, hence the\\n    verify-after-generation check in generate_suppressed_rollout below.\\n    """\\n    bad_words_ids = []\\n    seen = set()\\n    boundary_prefixes = ["", " ", "\\\\n", "\\\\n\\\\n", ". ", ", ", ": "]\\n    for phrase in SUPPRESSED_PHRASES:\\n        for boundary in boundary_prefixes:\\n            variant = boundary + phrase\\n            ids = tuple(tokenizer.encode(variant, add_special_tokens=False))\\n            if ids and ids not in seen:\\n                seen.add(ids)\\n                bad_words_ids.append(list(ids))\\n    return bad_words_ids\\n\', \'load_model_and_tokenizer\': \'def load_model_and_tokenizer(model_name: str):\\n    print(f"Loading tokenizer: {model_name}")\\n    tokenizer = AutoTokenizer.from_pretrained(model_name, trust_remote_code=True)\\n    if tokenizer.pad_token is None:\\n        tokenizer.pad_token = tokenizer.eos_token\\n\\n    print(f"Loading model (fp16)...")\\n    model = AutoModelForCausalLM.from_pretrained(\\n        model_name, torch_dtype=torch.float16, device_map="auto",\\n        trust_remote_code=True,\\n    )\\n    model.eval()\\n    print("Model loaded.")\\n    return model, tokenizer\\n\', \'generate_suppressed_rollout\': \'@torch.no_grad()\\ndef generate_suppressed_rollout(model, tokenizer, prefix_text: str, bad_words_ids, seed: int):\\n    torch.manual_seed(seed)\\n    inputs = tokenizer(prefix_text, return_tensors="pt", truncation=False).to(model.device)\\n    output_ids = model.generate(\\n        **inputs,\\n        max_new_tokens=ROLLOUT_MAX_NEW_TOKENS,\\n        do_sample=True,\\n        temperature=SAMPLE_TEMPERATURE,\\n        top_p=SAMPLE_TOP_P,\\n        bad_words_ids=bad_words_ids,\\n        pad_token_id=tokenizer.pad_token_id,\\n        eos_token_id=tokenizer.eos_token_id,\\n    )\\n    prompt_len = inputs["input_ids"].shape[1]\\n    new_tokens = output_ids[0][prompt_len:]\\n    full_response = tokenizer.decode(new_tokens, skip_special_tokens=False)\\n    return full_response\\n\'}, \'steering\': {\'N_ROLLOUTS\': \'N_ROLLOUTS = 8\\n\', \'ROLLOUT_MAX_NEW_TOKENS\': \'ROLLOUT_MAX_NEW_TOKENS = 2048\\n\', \'CHOSEN_ALPHA_MULTIPLIER\': \'CHOSEN_ALPHA_MULTIPLIER = {\\n    # Llama-8B: "wait" stayed at 100% across the ENTIRE 0.25-6.0 sweep -- not\\n    # moving this word is a known, accepted limitation here, not something\\n    # calibration failed to find. 1.5 chosen because coherence is solid (75%,\\n    # same as 2.0) and other words (actually, alternatively, verify) showed\\n    # real, consistent reduction at this strength -- no benefit to pushing\\n    # higher for a word that demonstrably won\\\'t move.\\n    "DeepSeek-R1-Distill-Llama-8B": 1.5,\\n\\n    # Qwen-1.5B: coherence collapses hard at 4.0+ (extraction 25%, 25%, 0%).\\n    # 3.0 is the highest usable point AND the only alpha showing any flagged-\\n    # rate reduction (100%->75%) with full coherence (100% extraction) --\\n    # the clear best point in the safe range.\\n    "DeepSeek-R1-Distill-Qwen-1.5B": 3.0,\\n\\n    # Qwen-7B: "wait" stayed at 100% across the entire sweep, same accepted\\n    # limitation as Llama-8B. 1.5 chosen for the same reason -- coherence\\n    # (50% extraction) is stable across 1.0-3.0, no gain from pushing further.\\n    "DeepSeek-R1-Distill-Qwen-7B": 1.5,\\n\\n    # Qwen-14B: the one clean, unconfounded result -- "wait" genuinely drops\\n    # 100%->50% at alpha=5.0 with coherence FULLY intact (100% extraction,\\n    # matching the alpha=0 baseline\\\'s own ceiling). No reason to prefer 6.0\\n    # over 5.0 since both give identical extraction/flagged rates.\\n    "DeepSeek-R1-Distill-Qwen-14B": 5.0,\\n}\\n\', \'build_prompt\': \'def build_prompt(problem: dict, tokenizer, model_name: str) -> str:\\n    is_reasoning = any(tag in model_name for tag in ["R1", "QwQ"])\\n    if problem["difficulty"] == "hard":\\n        instruction = ("Solve the following competition mathematics problem carefully. "\\n                        "Show your reasoning step by step and verify your answer.")\\n    else:\\n        instruction = ("Solve the following mathematics competition problem. "\\n                        "Show your working step by step.")\\n    if is_reasoning:\\n        messages = [{"role": "user", "content": f"{instruction}\\\\n\\\\nProblem: {problem[\\\'problem\\\']}"}]\\n    else:\\n        messages = [\\n            {"role": "system", "content": "You are an expert mathematician. Solve problems with "\\n                                          "clear step-by-step reasoning."},\\n            {"role": "user", "content": f"{instruction}\\\\n\\\\nProblem: {problem[\\\'problem\\\']}"}\\n        ]\\n    return tokenizer.apply_chat_template(messages, tokenize=False, add_generation_prompt=True)\\n\', \'get_decoder_layers\': \'def get_decoder_layers(model):\\n    assert hasattr(model, "model") and hasattr(model.model, "layers"), (\\n        "Expected model.model.layers (standard HF Llama/Qwen2 layout) -- this model\\\'s "\\n        "architecture doesn\\\'t match. Inspect model structure manually before proceeding."\\n    )\\n    return model.model.layers\\n\', \'make_steering_hook\': \'def make_steering_hook(direction_tensor, alpha):\\n    def hook(module, inputs, output):\\n        if isinstance(output, tuple):\\n            hidden_states = output[0] - alpha * direction_tensor\\n            return (hidden_states,) + output[1:]\\n        return output - alpha * direction_tensor\\n    return hook\\n\', \'generate_with_steering\': \'@torch.no_grad()\\ndef generate_with_steering(model, tokenizer, prefix_text, layer_idx, direction_tensor, alpha, seed):\\n    torch.manual_seed(seed)\\n    inputs = tokenizer(prefix_text, return_tensors="pt", truncation=False).to(model.device)\\n\\n    handle = None\\n    if alpha != 0.0:\\n        layers = get_decoder_layers(model)\\n        handle = layers[layer_idx].register_forward_hook(make_steering_hook(direction_tensor, alpha))\\n\\n    try:\\n        output_ids = model.generate(\\n            **inputs, max_new_tokens=ROLLOUT_MAX_NEW_TOKENS, do_sample=True,\\n            temperature=0.6, top_p=0.95,\\n            pad_token_id=tokenizer.pad_token_id, eos_token_id=tokenizer.eos_token_id,\\n        )\\n    finally:\\n        if handle is not None:\\n            handle.remove()  # always remove, even if generation raises -- verified in testing\\n\\n    prompt_len = inputs["input_ids"].shape[1]\\n    new_tokens = output_ids[0][prompt_len:]\\n    return tokenizer.decode(new_tokens, skip_special_tokens=False)\\n\'}}\nREFS["leak"] = {"EXPLICITLY_BANNED": \'EXPLICITLY_BANNED = [\\n    "wait", "actually", "let me reconsider", "that\\\'s wrong", "that is wrong",\\n    "i made an error", "let me try again", "this doesn\\\'t work",\\n    "this does not work", "i need to reconsider", "hmm", "that\\\'s not right",\\n    "that is not right", "let me rethink", "on second thought",\\n    "let me go back", "wait, let me", "actually, let me", "let me recheck",\\n    "let me re-check", "alternatively", "i made a mistake",\\n    "i think i made a mistake", "let me double check", "let me double-check",\\n    "hold on",\\n]\', "is_leaked": \'def is_leaked(text):\\n    t = text.lower()\\n    return any(p in t for p in EXPLICITLY_BANNED)\'}\nREFS["extractor"] = {\'boxed_spans\': \'def boxed_spans(text):\\n    spans = []\\n    for m in re.finditer(r\\\'\\\\\\\\boxed\\\\s*\\\\{\\\', text or ""):\\n        i = m.end() - 1\\n        depth = 0\\n        for j in range(i, len(text)):\\n            if text[j] == \\\'{\\\':\\n                depth += 1\\n            elif text[j] == \\\'}\\\':\\n                depth -= 1\\n                if depth == 0:\\n                    spans.append(text[i + 1:j])\\n                    break\\n    return spans\', \'normalise_answer\': \'def normalise_answer(s):\\n    if s is None:\\n        return "UNKNOWN"\\n    s = s.strip()\\n    s = s.replace("\\\\u0120", " ").replace("\\\\u010a", " ")\\n    s = re.sub(r\\\'^\\\\$+|\\\\$+$\\\', \\\'\\\', s)\\n    s = re.sub(r\\\'\\\\\\\\(?:left|right|,|;|!|quad|qquad)\\\', \\\'\\\', s)\\n    s = re.sub(r\\\'\\\\\\\\text\\\\s*\\\\{([^}]*)\\\\}\\\', r\\\'\\\\1\\\', s)\\n    s = s.replace(r\\\'\\\\dfrac\\\', r\\\'\\\\frac\\\').replace(r\\\'\\\\tfrac\\\', r\\\'\\\\frac\\\')\\n    s = re.sub(r\\\'\\\\\\\\frac\\\\s*\\\\{([^{}]*)\\\\}\\\\s*\\\\{([^{}]*)\\\\}\\\', r\\\'\\\\1/\\\\2\\\', s)\\n    s = re.sub(r\\\'\\\\s+\\\', \\\'\\\', s)\\n    s = s.rstrip(\\\'.,;:\\\')\\n    s = re.sub(r\\\'^\\\\{|\\\\}$\\\', \\\'\\\', s)\\n    return s or "UNKNOWN"\', \'extract_answer_new\': \'def extract_answer_new(text):\\n    boxed = boxed_spans(text)\\n    if boxed:\\n        return normalise_answer(boxed[-1])\\n    for pat in (r\\\'(?:final\\\\s+)?answer\\\\s*(?:is|=|:)\\\\s*(.{0,40})\\\',\\n                r\\\'(?:therefore|thus|hence)\\\\s*,?\\\\s*(.{0,40})\\\'):\\n        for m in re.finditer(pat, text, re.IGNORECASE):\\n            for tok in re.findall(r\\\'[-+]?\\\\$?\\\\\\\\?[0-9A-Za-z\\\\\\\\{}\\\\^_/\\\\.,]+\\\', m.group(1)):\\n                cand = normalise_answer(tok)\\n                if cand == "UNKNOWN" or cand.lower() in STOPWORDS:\\n                    continue\\n                if re.search(r\\\'[0-9]|\\\\\\\\\\\', cand):\\n                    return cand\\n    return "UNKNOWN"\', \'STOPWORDS\': \'STOPWORDS = {"the", "a", "an", "is", "approximately", "about", "roughly",\\n             "exactly", "correct", "incorrect", "therefore", "thus", "so",\\n             "then", "that", "this", "it", "equal", "equals", "our", "final",\\n             "answer", "value", "result", "less", "more", "different", "same",\\n             "indeed"}\'}\nORDER = {\n    "lexical":  ["N_ROLLOUTS", "ROLLOUT_MAX_NEW_TOKENS", "SAMPLE_TEMPERATURE",\n                 "SAMPLE_TOP_P", "SUPPRESSED_PHRASES", "build_prompt",\n                 "build_bad_words_ids", "load_model_and_tokenizer",\n                 "generate_suppressed_rollout"],\n    "steering": ["N_ROLLOUTS", "ROLLOUT_MAX_NEW_TOKENS", "CHOSEN_ALPHA_MULTIPLIER",\n                 "build_prompt", "get_decoder_layers", "make_steering_hook",\n                 "generate_with_steering"],\n    "leak":     ["EXPLICITLY_BANNED", "is_leaked"],\n    "extractor": ["STOPWORDS", "boxed_spans", "normalise_answer", "extract_answer_new"],\n}\nHEADER = ("import re, json, time\\nimport torch\\n"\n          "from transformers import AutoTokenizer, AutoModelForCausalLM\\n")\n\ndef embedded_source(kind):\n    return "\\n\\n".join(REFS[kind][k] for k in ORDER[kind])\n\ndef fingerprint(kind):\n    return hashlib.sha256(embedded_source(kind).encode()).hexdigest()[:16]\n\ndef build_module(kind):\n    src = (HEADER if kind in ("lexical", "steering") else "import re\\n") + embedded_source(kind)\n    m = types.ModuleType(f"embedded_{kind}")\n    exec(compile(src, f"<embedded {kind}>", "exec"), m.__dict__)\n    fp = fingerprint(kind)\n    print(f"  {kind}: embedded production code (fingerprint {fp})")\n    return m, {"label": kind, "file": "embedded in redraw_necessity.py", "sha256_16": fp}\n\ndef _top_nodes(txt):\n    out = {}\n    for n in ast.parse(txt).body:\n        if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)):\n            out[n.name] = n\n        elif isinstance(n, ast.Assign) and len(n.targets) == 1 and isinstance(n.targets[0], ast.Name):\n            out[n.targets[0].id] = n\n    return out\n\nREFS["scorer"] = {"load_gt": \'def load_gt(use_repaired):\\n    """Ground truth. If use_repaired, prefer the dataset-derived answers from\\n    the audit over the Stage-1 values, which were truncated for 71 problems."""\\n    gt = {}\\n    for p in (EVENTS_REV, EVENTS_FIL):\\n        if p.exists():\\n            for e in json.load(open(p)):\\n                gt[(e["model"], e["problem_id"])] = e["answer_gt"]\\n    n_repaired = 0\\n    if use_repaired and REPAIRED_GT.exists():\\n        rep = json.load(open(REPAIRED_GT))\\n        for k, v in rep.items():\\n            model, pid = k.split("|", 1)\\n            if (model, pid) in gt and v.get("true_answer_gt"):\\n                gt[(model, pid)] = v["true_answer_gt"]\\n                n_repaired += 1\\n    return gt, n_repaired\', "necessity_scores": \'def necessity_scores(path, gt, parser, unknown_mode):\\n    """unknown_mode: \\\'as_incorrect\\\' | \\\'dropped\\\' | \\\'as_correct\\\'."""\\n    out = []\\n    for r in json.load(open(path)):\\n        g = gt.get((r["model"], r["problem_id"]))\\n        texts = r.get("rollout_texts", [])\\n        if g is None or not texts:\\n            continue\\n        vals = []\\n        for t in texts:\\n            a = parser(t)\\n            unk = (a == "UNKNOWN")\\n            if unk and unknown_mode == "dropped":\\n                continue\\n            if unk:\\n                correct = (unknown_mode == "as_correct")\\n            else:\\n                correct = (normalise_answer(a) == normalise_answer(g))\\n            vals.append(correct)\\n        if vals:\\n            out.append({"model": r["model"], "problem_id": r["problem_id"],\\n                        "human_label": r.get("human_label"),\\n                        "necessity": 1.0 - sum(vals) / len(vals)})\\n    return out\'}\nORDER["scorer"] = ["load_gt", "necessity_scores"]\nEVENTS_REV_OLD = EXPORT / "counterfactual_pilot_events.json"\nEVENTS_FIL_OLD = EXPORT / "filler_control_pilot_events.json"\nREPAIRED_GT = EXPORT / "repaired_ground_truth.json"\n\ndef lift_scorer():\n    """The corrected scorer, all embedded: extractor (see REFS[\'extractor\'])\n    plus load_gt / necessity_scores verbatim from\n    superseded/necessity_verification_and_leak_audit.ipynb, section 1\n    (= notebook \'Verification and audits\', section 1). load_gt reads the\n    answer_gt of the published 83/80 events and overrides it with the\n    dataset-derived answer in repaired_ground_truth.json."""\n    m, _ = build_module("extractor")\n    m.json = json\n    m.EVENTS_REV, m.EVENTS_FIL, m.REPAIRED_GT = EVENTS_REV_OLD, EVENTS_FIL_OLD, REPAIRED_GT\n    exec(compile(embedded_source("scorer"), "<embedded scorer>", "exec"), m.__dict__)\n    gt, n_rep = m.load_gt(use_repaired=True)\n    print(f"  scorer: embedded (extractor {fingerprint(\'extractor\')}, "\n          f"load_gt/necessity_scores {fingerprint(\'scorer\')})")\n    print(f"    load_gt(use_repaired=True) -> {len(gt)} entries, "\n          f"{len({k[1] for k in gt})} problems, {n_rep} repaired")\n    return m, gt, {"label": "scorer", "file": "embedded",\n                   "extractor_fingerprint": fingerprint("extractor"),\n                   "scorer_fingerprint": fingerprint("scorer")}\n\ndef load_gt_all_traces():\n    """Ground truth for EVERY trace (redraw sample only): the dataset-derived\n    answer from repaired_ground_truth.json, falling back to the stored one."""\n    rep = rjson(REPAIRED_GT, {}) or {}\n    gt = {}\n    for k, v in rep.items():\n        model, pid = k.split("|", 1)\n        a = v.get("true_answer_gt") or v.get("stored_answer_gt")\n        if a: gt[(model, pid)] = a\n    print(f"    all-trace ground truth: {len(gt)} (model, problem) entries")\n    return gt\n\n\n# ---------------------------------------------------------------------------\n# text helpers (verbatim from the \'Check 8\' repetition analysis,\n# superseded/audits_during_revision.ipynb §16)\n# ---------------------------------------------------------------------------\n_TOK = re.compile(r"[a-z0-9]+")\ndef toks(s): return set(_TOK.findall(s.lower()))\n\ndef max_jaccard(before, after):\n    bs = [toks(s) for s in before]; as_ = [toks(s) for s in after]\n    best = 0.0\n    for b in bs:\n        if not b: continue\n        for a in as_:\n            if not a: continue\n            i = len(b & a)\n            if i:\n                j = i / len(b | a)\n                if j > best: best = j\n    return float(best)\n\n_SENT = re.compile(r\'(?<=[.!?])\\s+\')\ndef split_sentences(t): return [s for s in _SENT.split(t) if s.strip()]\n\ndef take_by_budget(sents, budget, from_end):\n    out, used = [], 0\n    for s in (reversed(sents) if from_end else sents):\n        if used + len(s) > budget and out: break\n        out.append(s); used += len(s)\n    return list(reversed(out)) if from_end else out\n\ndef extract_window(fr, cs, ce, BB=900, BA=700, RB=2500, RA=1200, NB=6, NA=6):\n    rs = max(0, cs - RB); re_ = min(len(fr), ce + RA)\n    w = fr[rs:re_]\n    ls, le = cs - rs, ce - rs\n    if not (0 <= ls <= le <= len(w)): return None, None\n    bef = take_by_budget(split_sentences(w[:ls]), BB, True)\n    aft = take_by_budget(split_sentences(w[le:]), BA, False)\n    if aft and not re.search(r\'[.!?]\\s*$\', aft[-1]): aft = aft[:-1]\n    bef, aft = bef[-NB:], aft[:NA]\n    if not bef or not aft: return None, None\n    return bef, aft\n\n# length-preserving; used ONLY for offset verification and windows, exactly as\n# Check 8 did, so the repetition covariate is comparable with the old one\n_LP = {"Ġ": " ", "Ċ": "\\n", "Ģ": "\\n", "▁": " "}\ndef clean_lp(t):\n    s = t or ""\n    for k, v in _LP.items(): s = s.replace(k, v)\n    return s\n\n# proper byte-level-BPE decoding (GPT-2 bytes_to_unicode inverse), used for\n# the PREFIX the model is conditioned on. Not length-preserving, so it is\n# applied to a slice that has already been cut at the verified offset.\ndef _byte_decoder():\n    bs = (list(range(ord("!"), ord("~") + 1)) +\n          list(range(ord("¡"), ord("¬") + 1)) +\n          list(range(ord("®"), ord("ÿ") + 1)))\n    cs = bs[:]; n = 0\n    for b in range(256):\n        if b not in bs:\n            bs.append(b); cs.append(256 + n); n += 1\n    return {chr(c): b for b, c in zip(bs, cs)}\nBYTE_DEC = _byte_decoder()\n\ndef restore_text(s):\n    """-> (text, path). \'clean\': no BPE markers. \'bpe_decoded\': the string was\n    entirely in byte-level character space (no real spaces) and was decoded\n    exactly. \'mixed_minimal\': markers alongside real spaces; only Ġ/Ċ/ĉ are\n    mapped back, and the event is flagged."""\n    if "Ġ" not in s and "Ċ" not in s and "ĉ" not in s:\n        return s, "clean"\n    if " " not in s:\n        try:\n            return (bytes(BYTE_DEC[ch] for ch in s)\n                    .decode("utf-8", errors="replace"), "bpe_decoded")\n        except KeyError:\n            pass\n    return (s.replace("Ġ", " ").replace("Ċ", "\\n")\n             .replace("ĉ", "\\t"), "mixed_minimal")\n\ndef marker_at(full, cs, marker):\n    """Check 8\'s verification: the marker must sit at cs in the trace."""\n    mk = clean_lp(str(marker or "")).strip()\n    txt = clean_lp(full or "")\n    if cs is None or not mk: return False\n    try: cs = int(cs)\n    except Exception: return False\n    return 0 <= cs < len(txt) and txt[cs:cs + len(mk)].lower() == mk.lower()\n\ndef rep_at(full, cs, ce, marker):\n    txt = clean_lp(full or "")\n    mk = clean_lp(str(marker or "")).strip()\n    if ce is None: ce = int(cs) + max(len(mk), 1)\n    b, a = extract_window(txt, int(cs), int(ce))\n    return None if b is None else max_jaccard(b, a)\n\n\n# ---------------------------------------------------------------------------\n# estimators (verbatim from the same §16)\n# ---------------------------------------------------------------------------\ndef ls_fit(Y, X):\n    b, *_ = np.linalg.lstsq(X, Y, rcond=None); return b\n\ndef cluster_boot(Y, X, groups, nb=N_BOOT, seed=8080):\n    beta = ls_fit(Y, X); rng = np.random.RandomState(seed)\n    gi = defaultdict(list)\n    for i, g in enumerate(groups): gi[g].append(i)\n    arrs = [np.array(v) for v in gi.values()]; G = len(arrs)\n    D = np.empty((nb, X.shape[1]))\n    for k in range(nb):\n        idx = np.concatenate([arrs[j] for j in rng.randint(0, G, G)])\n        D[k] = ls_fit(Y[idx], X[idx])\n    return beta, D, G\n\ndef ci_p(col):\n    lo, hi = np.percentile(col, [2.5, 97.5])\n    p = 2 * min((col <= 0).mean(), (col >= 0).mean())\n    return float(lo), float(hi), float(min(1.0, max(p, 1.0 / len(col))))\n\ndef boot_mean_diff(a, b, ga, gb, nb=N_BOOT, seed=8080):\n    rng = np.random.RandomState(seed)\n    by = defaultdict(lambda: ([], []))\n    for v, g in zip(a, ga): by[g][0].append(v)\n    for v, g in zip(b, gb): by[g][1].append(v)\n    keys = list(by); G = len(keys); out = []\n    for _ in range(nb):\n        pick = [keys[j] for j in rng.randint(0, G, G)]\n        A = [v for k in pick for v in by[k][0]]\n        B = [v for k in pick for v in by[k][1]]\n        if A and B: out.append(np.mean(A) - np.mean(B))\n    out = np.array(out)\n    lo, hi = np.percentile(out, [2.5, 97.5])\n    return float(lo), float(hi), int(G)\n\ndef pfmt(p, nb=N_BOOT):\n    return f"< {1/nb:.2g} (floor)" if p <= 1/nb + 1e-12 else f"{p:.4g}"\n\n\n# ---------------------------------------------------------------------------\n# helpers shared by the stages\n# ---------------------------------------------------------------------------\ndef event_key(e):\n    return (e["arm"], e["model"], str(e["problem_id"]), int(e["char_start"]))\n\n_tr = {}\ndef trace(model, pid):\n    k = (model, str(pid))\n    if k not in _tr:\n        _tr[k] = rjson(TRACES / model / f"{pid}.json")\n    return _tr[k]\n\n\n# #############################################################################\n# STAGE: select\n# #############################################################################\ndef stage_select():\n    t0 = time.time()\n    hdr("SELECT — building the redrawn event sets")\n    prod, _gt_events, src_scorer = lift_scorer()\n    gt = load_gt_all_traces()\n    # the filler-arm notebook\'s normaliser, verbatim\n    def normalize_marker(text):\n        return re.sub(r"[^\\w\\s]", "", str(text).lower()).strip()\n    src_norm = {"label": "marker normaliser", "file": "embedded"}\n    print(f"    normalize_marker(\'Wait,\') = {normalize_marker(\'Wait,\')!r}")\n\n    # ---- 1. eligible traces, CORRECTED parser ------------------------------\n    hdr("1 — eligible traces (corrected parser, not truncated)")\n    elig, why_t = {}, Counter()\n    parse_disagree = 0\n    for model in MODELS:\n        d = TRACES / model\n        if not d.is_dir(): continue\n        for p in sorted(d.glob("*.json")):\n            pid = p.stem\n            tr = rjson(p)\n            if tr is None: why_t["unreadable"] += 1; continue\n            if tr.get("truncated", False):\n                why_t["truncated"] += 1; elig[(model, pid)] = False; continue\n            g = gt.get((model, pid))\n            if g is None:\n                why_t["no repaired ground truth"] += 1\n                elig[(model, pid)] = False; continue\n            raw = tr.get("full_response", "") or ""\n            text, _ = restore_text(raw)\n            a = prod.extract_answer_new(text)\n            a_raw = prod.extract_answer_new(raw)\n            if (a == "UNKNOWN") != (a_raw == "UNKNOWN") or (\n                    a != "UNKNOWN" and a_raw != "UNKNOWN" and\n                    prod.normalise_answer(a) != prod.normalise_answer(a_raw)):\n                parse_disagree += 1\n            if a == "UNKNOWN":\n                why_t["corrected parser: UNKNOWN"] += 1\n                elig[(model, pid)] = False; continue\n            ok = prod.normalise_answer(a) == prod.normalise_answer(g)\n            why_t["correct" if ok else "incorrect"] += 1\n            elig[(model, pid)] = ok\n    n_elig = sum(elig.values())\n    print(f"  traces scanned: {len(elig)}   eligible: {n_elig}")\n    for k, v in why_t.most_common(): print(f"      {v:>6}  {k}")\n    print(f"  traces where parsing raw vs restored text disagrees: "\n          f"{parse_disagree}  (expect ~0)")\n\n    # ---- 2. pools, with verified offsets -----------------------------------\n    hdr("2 — revision and filler pools (offset verified)")\n    rev_pool, fil_pool, why_r, why_f = [], [], Counter(), Counter()\n    for model in MODELS:\n        d = LABELS / model\n        if not d.is_dir(): continue\n        for p in sorted(d.glob("*.json")):\n            o = rjson(p) or {}\n            pid = str(o.get("problem_id", p.stem))\n            for rv in (o.get("revisions") or []):\n                if not rv.get("verified", True): continue\n                why_r["verified revision"] += 1\n                if not elig.get((model, pid)):\n                    why_r["trace not eligible"] += 1; continue\n                tr = trace(model, pid)\n                mk = str(rv.get("matched_text") or rv.get("marker_phrase") or "")\n                cs = rv.get("char_start")\n                if not marker_at(tr.get("full_response", ""), cs, mk):\n                    why_r["marker not at offset"] += 1; continue\n                why_r["eligible"] += 1\n                rev_pool.append({"arm": "revision", "model": model,\n                                 "problem_id": pid, "char_start": int(cs),\n                                 "char_end": rv.get("char_end"),\n                                 "marker_phrase": mk,\n                                 "marker_norm": normalize_marker(mk)})\n        rp = REJECTS / f"{model}_confirmed_filler.json"\n        for fl in (rjson(rp) or []):\n            pid = str(fl.get("problem_id"))\n            why_f["confirmed filler"] += 1\n            if not elig.get((model, pid)):\n                why_f["trace not eligible"] += 1; continue\n            tr = trace(model, pid)\n            mk = str(fl.get("matched_text") or fl.get("marker") or "")\n            cs = fl.get("char_start")\n            if not marker_at(tr.get("full_response", ""), cs, mk):\n                why_f["marker not at offset"] += 1; continue\n            why_f["eligible"] += 1\n            fil_pool.append({"arm": "filler", "model": model,\n                             "problem_id": pid, "char_start": int(cs),\n                             "char_end": (int(cs) + len(mk)),\n                             "marker_phrase": mk,\n                             "marker_norm": normalize_marker(mk)})\n    for lab, w in (("revision", why_r), ("filler", why_f)):\n        print(f"  {lab}:")\n        for k, v in w.most_common(): print(f"      {v:>6}  {k}")\n    print(f"  pool sizes: {len(rev_pool)} revision / {len(fil_pool)} filler")\n\n    # ---- 3. old-sample prefix contamination, for the record ----------------\n    hdr("3 — were the OLD 83/80 prefixes contaminated with BPE markers?")\n    old_rep = {}\n    for nm_, p in (("old revision", EXPORT / "counterfactual_pilot_events.json"),\n                   ("old filler", EXPORT / "filler_control_pilot_events.json")):\n        evs = rjson(p, []) or []\n        by = defaultdict(Counter)\n        for e in evs:\n            s = e.get("prefix_response_text") or ""\n            by[e["model"]][restore_text(s)[1]] += 1\n        print(f"  {nm_} ({len(evs)} events):")\n        for m, c in sorted(by.items()):\n            print(f"      {m[-14:]:<16}{dict(c)}")\n        old_rep[nm_] = {m: dict(c) for m, c in by.items()}\n    print("""\n  \'bpe_decoded\' or \'mixed_minimal\' means that event\'s rollouts were generated\n  from a prefix containing literal BPE marker characters. Matched across arms,\n  so it does not bias the revision-filler DIFFERENCE by construction, but it is\n  a fidelity problem for those events and belongs in the paper if it occurred.""")\n\n    # ---- 4. uniform draw, then 1:1 matching --------------------------------\n    hdr(f"4 — uniform draw of the revision arm, 1:1 filler matching "\n        f"(target {N_PAIRS} pairs)")\n    rng_s = random.Random(SEEDS["select"])\n    rng_m = random.Random(SEEDS["match"])\n    order = rev_pool[:]; rng_s.shuffle(order)\n    by_cell = defaultdict(list)\n    for f in fil_pool: by_cell[(f["model"], f["marker_norm"])].append(f)\n    for v in by_cell.values(): rng_m.shuffle(v)\n    used, pairs, skipped = defaultdict(int), [], Counter()\n    for r in order:\n        if len(pairs) >= N_PAIRS: break\n        cell = (r["model"], r["marker_norm"])\n        if used[cell] >= len(by_cell.get(cell, [])):\n            skipped[cell] += 1; continue\n        f = by_cell[cell][used[cell]]; used[cell] += 1\n        pairs.append((r, f))\n    n_seen = sum(skipped.values()) + len(pairs)\n    print(f"  revisions examined in random order: {n_seen}")\n    print(f"  pairs formed: {len(pairs)}")\n    print(f"  revisions skipped, no filler left in their (model, marker) cell: "\n          f"{sum(skipped.values())}")\n    for (m, mk), c in skipped.most_common(8):\n        print(f"      {m[-14:]:<16}{mk!r:<26}{c}")\n    if len(pairs) < N_PAIRS:\n        print(f"  WARNING: only {len(pairs)} pairs available — the matchable "\n              f"pool is the binding constraint, not N_PAIRS.")\n    print("""\n  DISCLOSE: the revision arm is uniform among revisions whose (model, marker)\n  cell still had an unused filler. Skipped revisions are concentrated in\n  markers fillers rarely carry, so the matched arm over-represents common\n  markers relative to the revision population. The composition table below\n  is the evidence.""")\n\n    old_keys = set()\n    for p, arm in ((EXPORT / "counterfactual_pilot_events.json", "revision"),\n                   (EXPORT / "filler_control_pilot_events.json", "filler")):\n        for e in rjson(p, []) or []:\n            if e.get("char_start") is not None:\n                old_keys.add((arm, e["model"], str(e["problem_id"]),\n                              int(e["char_start"])))\n\n    def finish(e, k):\n        tr = trace(e["model"], e["problem_id"])\n        full = tr.get("full_response", "") or ""\n        prefix, path = restore_text(full[:e["char_start"]])\n        e.update({"eid": f"{e[\'arm\'][0].upper()}{k:04d}",\n                  "problem": tr.get("problem", ""),\n                  "difficulty": tr.get("difficulty", "hard"),\n                  "answer_gt": str(gt.get((e["model"], e["problem_id"]))),\n                  "prefix_response_text": prefix,\n                  "prefix_restore_path": path,\n                  "in_old_sample": event_key(e) in old_keys,\n                  "repetition": rep_at(full, e["char_start"], e.get("char_end"),\n                                       e["marker_phrase"])})\n        return e\n    revs = [finish(dict(r), k) for k, (r, _) in enumerate(pairs)]\n    fils = [finish(dict(f), k) for k, (_, f) in enumerate(pairs)]\n    wjson(revs, EV_REV); wjson(fils, EV_FIL)\n\n    hdr("5 — composition of the drawn sample")\n    for lab, arr in (("revision", revs), ("filler", fils)):\n        print(f"  {lab}: {len(arr)} events, "\n              f"{len({e[\'problem_id\'] for e in arr})} problems, "\n              f"{len({(e[\'model\'], e[\'problem_id\']) for e in arr})} traces")\n        print(f"      by model : {dict(Counter(e[\'model\'][-12:] for e in arr))}")\n        print(f"      by marker: {dict(Counter(e[\'marker_norm\'] for e in arr).most_common(8))}")\n        print(f"      prefix   : {dict(Counter(e[\'prefix_restore_path\'] for e in arr))}")\n        print(f"      in old sample: {sum(e[\'in_old_sample\'] for e in arr)}")\n    rr = [e["repetition"] for e in revs if e["repetition"] is not None]\n    rf = [e["repetition"] for e in fils if e["repetition"] is not None]\n    if rr and rf:\n        print(f"  repetition: revision {np.mean(rr):.4f}  filler {np.mean(rf):.4f}"\n              f"  (old sample: 0.4014 / 0.4826)")\n    print(f"\\n  wrote {EV_REV.name}, {EV_FIL.name}")\n    est = len(pairs) * 2 * 0.146   # measured: 526 s per event on an A100 (Oct 29 run)\n    print(f"  estimated GPU time per intervention: ~{est:.0f} A100-hours")\n\n    manifest_add({"stage": "select", "started": datetime.fromtimestamp(t0, timezone.utc).isoformat(),\n                  "finished": now(), "wall_clock_s": round(time.time() - t0, 1),\n                  "env": env_info(), "seeds": SEEDS, "n_pairs_target": N_PAIRS,\n                  "n_pairs": len(pairs), "eligible_traces": n_elig,\n                  "trace_reasons": dict(why_t), "revision_reasons": dict(why_r),\n                  "filler_reasons": dict(why_f),\n                  "pool": {"revision": len(rev_pool), "filler": len(fil_pool)},\n                  "skipped_unmatchable": sum(skipped.values()),\n                  "old_prefix_contamination": old_rep,\n                  "parse_raw_vs_restored_disagree": parse_disagree,\n                  "sources": [src_scorer, src_norm]})\n\n\n\n# #############################################################################\n# STAGE: select, SAMPLE = "original"\n#   The published 83 revision + 80 filler events, unchanged in identity\n#   (model, problem_id, char_start, marker, label), rebuilt with:\n#     - prefix = restore_text(full_response[:char_start])  (no BPE characters)\n#     - the corrected parser\'s repaired ground truth\n#     - event-keyed resume (fixes the two lexical events never generated)\n#   Nothing about WHICH events are used changes.\n# #############################################################################\ndef _short(m): return str(m).split("/")[-1]\n\ndef stage_select_original():\n    t0 = time.time()\n    hdr("SELECT (original sample) — the published 83/80, clean prefixes")\n    prod, gt, src_scorer = lift_scorer()\n    out, why = {"revision": [], "filler": []}, Counter()\n    for arm, path in (("revision", EXPORT / "counterfactual_pilot_events.json"),\n                      ("filler",   EXPORT / "filler_control_pilot_events.json")):\n        evs = rjson(path, []) or []\n        print(f"\\n  {arm}: {len(evs)} events from {path.name}")\n        for k, e in enumerate(evs):\n            model = _short(e["model"])\n            if model not in MODELS:\n                why[f"{arm}: model not in RERUN_MODELS"] += 1; continue\n            pid, cs = str(e["problem_id"]), e.get("char_start")\n            mk = str(e.get("marker_phrase") or e.get("matched_text")\n                     or e.get("marker") or "")\n            tr = trace(model, pid)\n            if tr is None or cs is None:\n                why[f"{arm}: no trace / no char_start"] += 1; continue\n            full = tr.get("full_response", "") or ""\n            cs = int(cs)\n            old_prefix = e.get("prefix_response_text")\n            same = (old_prefix == full[:cs]) if old_prefix is not None else None\n            if mk:\n                if not marker_at(full, cs, mk):\n                    why[f"{arm}: marker not at offset"] += 1; continue\n            elif not same:\n                # no marker stored: the offset is verified by the stored\n                # prefix being exactly the trace slice instead\n                why[f"{arm}: no marker and stored prefix != trace slice"] += 1\n                continue\n            else:\n                why[f"{arm}: verified by stored prefix (no marker field)"] += 1\n            why[f"{arm}: stored prefix == full_response[:cs]: {same}"] += 1\n            prefix, rpath = restore_text(full[:cs])\n            why[f"{arm}: prefix {rpath}"] += 1\n            g = gt.get((model, pid))\n            if g is None:\n                why[f"{arm}: no repaired ground truth"] += 1; continue\n            ce = e.get("char_end") or (cs + len(mk))\n            out[arm].append({\n                "arm": arm, "eid": f"{arm[0].upper()}O{k:04d}",\n                "old_eid": e.get("eid"), "round": e.get("round"),\n                "human_label": e.get("human_label"),\n                "model": model, "problem_id": pid, "char_start": cs,\n                "char_end": ce, "marker_phrase": mk,\n                "problem": tr.get("problem", ""),\n                "difficulty": tr.get("difficulty", "hard"),\n                "answer_gt": str(g),\n                "prefix_response_text": prefix, "prefix_restore_path": rpath,\n                "old_prefix_had_bpe": bool(old_prefix and ("Ġ" in old_prefix\n                                                           or "Ċ" in old_prefix)),\n                "in_old_sample": True,\n                "repetition": rep_at(full, cs, ce, mk)})\n    for k, v in sorted(why.items()): print(f"      {v:>5}  {k}")\n    for arm in ("revision", "filler"):\n        a = out[arm]\n        print(f"\\n  {arm}: {len(a)} events kept  by model "\n              f"{dict(Counter(e[\'model\'][-12:] for e in a))}")\n        print(f"      prefix paths: {dict(Counter(e[\'prefix_restore_path\'] for e in a))}"\n              f"   old prefix had BPE: {sum(e[\'old_prefix_had_bpe\'] for e in a)}")\n    ex = next((e for e in out["revision"] if e["prefix_restore_path"] != "clean"), None)\n    if ex:\n        print(f"\\n  example restored tail ({ex[\'model\'][-12:]}): "\n              f"{ex[\'prefix_response_text\'][-80:]!r}")\n    # same model, same input => the restored prefix must re-tokenize to the\n    # ids the model originally generated; checked here on the cheap (tokenizer\n    # only, no weights)\n    try:\n        from transformers import AutoTokenizer\n        for model in MODELS:\n            sub = [e for e in out["revision"] + out["filler"] if e["model"] == model]\n            if not sub: continue\n            tok = AutoTokenizer.from_pretrained(f"deepseek-ai/{model}")\n            bad = sum(1 for e in sub if any(c in e["prefix_response_text"]\n                                            for c in "ĠĊ"))\n            n_tok = [len(tok(e["prefix_response_text"], add_special_tokens=False)\n                         ["input_ids"]) for e in sub[:5]]\n            print(f"  {model[-14:]:<16}restored prefixes still containing Ġ/Ċ: {bad}"\n                  f"   token lengths of first 5 prefixes: {n_tok}")\n    except Exception as ex_:\n        print(f"  (tokenizer check skipped: {type(ex_).__name__}: {ex_})")\n    wjson(out["revision"], EV_REV); wjson(out["filler"], EV_FIL)\n    n = len(out["revision"]) + len(out["filler"])\n    print(f"\\n  wrote {EV_REV} and {EV_FIL.name}")\n    print(f"  {n} events x 8 rollouts per intervention: ~{n*0.146:.0f} A100-h "\n          f"per intervention at the measured 0.146 A100-h/event.")\n    manifest_add({"stage": "select_original",\n                  "started": datetime.fromtimestamp(t0, timezone.utc).isoformat(),\n                  "finished": now(), "wall_clock_s": round(time.time() - t0, 1),\n                  "env": env_info(), "seeds": SEEDS, "models": MODELS,\n                  "reasons": dict(why),\n                  "n": {a: len(out[a]) for a in out}, "sources": [src_scorer]})\n\n# #############################################################################\n# STAGES: lexical / steering\n# #############################################################################\ndef stage_generate(intervention):\n    t0 = time.time()\n    hdr(f"GENERATE — {intervention}")\n    revs, fils = rjson(EV_REV), rjson(EV_FIL)\n    if not revs or not fils:\n        raise SystemExit("run STAGE = \'select\' first")\n\n    if intervention == "lexical":\n        gen, src_gen = build_module("lexical")\n        print(f"    SUPPRESSED_PHRASES: {len(gen.SUPPRESSED_PHRASES)}")\n        loader = gen.load_model_and_tokenizer\n        sources = [src_gen]\n    else:\n        gen, src_gen = build_module("steering")\n        lex, src_lex = build_module("lexical")      # model loader only\n        loader = lex.load_model_and_tokenizer\n        dirs_file = (EXPORT / "steering_directions_llama8b_reextract.json"\n                     if intervention == "steering_llama8b_reextract" else EXPORT / "steering_directions.json")\n        if not dirs_file.exists():\n            raise SystemExit(f"{dirs_file.name} not found (run 11_reextract_llama8b.py stage \'direction\' first)")\n        print(f"    directions: {dirs_file.name}")\n        dirs = rjson(dirs_file) or {}\n        dirs = dirs.get("models", dirs) if isinstance(dirs, dict) else {}\n        alpha_k = gen.CHOSEN_ALPHA_MULTIPLIER\n        print(f"    alpha multipliers: {alpha_k}")\n        sources = [src_gen, src_lex]\n    GEN_FP = src_gen["sha256_16"]\n    n_roll = int(gen.N_ROLLOUTS)\n    print(f"    N_ROLLOUTS={n_roll}  max_new_tokens={gen.ROLLOUT_MAX_NEW_TOKENS}")\n    lk, src_lk = build_module("leak")\n    leak = lk.is_leaked; sources.append(src_lk)\n\n    results = {}\n    for arm in ("revision", "filler"):\n        recs_ = rjson(ROLL[(intervention, arm)], []) or []\n        want = SEEDS["rollout_base"][intervention]\n        stale = [r for r in recs_ if r.get("generator_fingerprint") != GEN_FP\n                 or (r.get("seeds") or [want])[0] != want]\n        if stale:\n            arch = Path(str(ROLL[(intervention, arm)]).replace(\n                ".json", f"_ARCHIVED_not_production_{datetime.now():%Y%m%d_%H%M%S}.json"))\n            wjson(recs_, arch)\n            print(f"  {arm}: {len(stale)} of {len(recs_)} existing records were made by a "\n                  f"different generator or seed set -> whole file archived to {arch.name}; starting fresh")\n            recs_ = []\n        results[arm] = recs_\n    done = {(r["arm"], r["model"], str(r["problem_id"]), int(r["char_start"]))\n            for arm in results for r in results[arm]}\n    print(f"  rollout seeds: {SEEDS[\'rollout_base\'][intervention]} + r   -> {ROLL[(intervention, \'revision\')].name}")\n    print(f"  resuming: {len(done)} events already complete (keyed on the event)")\n\n    import torch\n    gpu = torch.cuda.get_device_name(0) if torch.cuda.is_available() else "none"\n    per_model_time = {}\n    for model in ([LLAMA] if intervention == "steering_llama8b_reextract" else MODELS):\n        todo = [e for e in revs + fils\n                if e["model"] == model and event_key(e) not in done]\n        if not todo:\n            print(f"\\n  {model}: nothing to do"); continue\n        tm = time.time()\n        full = model if "/" in model else f"deepseek-ai/{model}"\n        print(f"\\n  {model}: {len(todo)} events", flush=True)\n        mdl, tok = loader(full)\n        if intervention == "lexical":\n            bad = gen.build_bad_words_ids(tok)\n            print(f"    {len(bad)} banned token sequences (the pilot ban gave 54)")\n        else:\n            info = dirs.get(model)\n            if not info:\n                print(f"    no steering direction for {model}; skipped"); continue\n            layer = int(info.get("layer", info.get("layer_idx")))\n            alpha = float(alpha_k[model]) * float(info["raw_direction_norm"])\n            direction = torch.tensor(info["unit_direction"], dtype=torch.float16,\n                                     device=mdl.device)\n            print(f"    layer {layer}  k={alpha_k[model]}  alpha={alpha:.3f}")\n        for e in todo:\n            te = time.time()\n            prefix = gen.build_prompt({"problem": e["problem"],\n                                       "difficulty": e["difficulty"]},\n                                      tok, full) + e["prefix_response_text"]\n            texts = []\n            for r in range(n_roll):\n                seed = SEEDS["rollout_base"][intervention] + r\n                if intervention == "lexical":\n                    t = gen.generate_suppressed_rollout(mdl, tok, prefix, bad, seed)\n                else:\n                    t = gen.generate_with_steering(mdl, tok, prefix, layer,\n                                                   direction, alpha, seed)\n                texts.append(t)\n            rec = {"arm": e["arm"], "eid": e["eid"], "model": model,\n                   "problem_id": e["problem_id"], "char_start": e["char_start"],\n                   "marker_phrase": e["marker_phrase"],\n                   "rollout_texts": texts,\n                   "seeds": [SEEDS["rollout_base"][intervention] + r for r in range(n_roll)],\n                   "leaked": ([bool(leak(t)) for t in texts] if leak else None),\n                   "generator_fingerprint": GEN_FP,\n                   "n_banned_sequences": (len(bad) if intervention == "lexical" else None),\n                   "wall_clock_s": round(time.time() - te, 1), "gpu": gpu}\n            results[e["arm"]].append(rec)\n            wjson(results[e["arm"]], ROLL[(intervention, e["arm"])])\n            print(f"    {e[\'eid\']} {e[\'problem_id\']:<12} "\n                  f"{rec[\'wall_clock_s\']:>6.0f}s", flush=True)\n        per_model_time[model] = round(time.time() - tm, 1)\n        del mdl\n        torch.cuda.empty_cache()\n\n    manifest_add({"stage": intervention,\n                  "started": datetime.fromtimestamp(t0, timezone.utc).isoformat(),\n                  "finished": now(), "wall_clock_s": round(time.time() - t0, 1),\n                  "per_model_wall_clock_s": per_model_time,\n                  "env": env_info(), "seeds": SEEDS, "n_rollouts": n_roll,\n                  "generator_fingerprint": GEN_FP, "sources": sources})\n    print(f"\\n  done. {intervention} wall clock {time.time()-t0:.0f}s on {gpu}")\n\n\n# #############################################################################\n# STAGE: analyze\n# #############################################################################\ndef stage_analyze():\n    t0 = time.time()\n    hdr(f"ANALYZE — {SAMPLE} sample, beside the old 83/80")\n    prod, gt, src_scorer = lift_scorer()\n    try:\n        print("\\n  necessity_scores source (first 30 lines), for the record:")\n        for ln in REFS["scorer"]["necessity_scores"].splitlines()[:30]:\n            print(f"    | {ln}")\n    except Exception as e:\n        print(f"    (source not retrievable: {e})")\n\n    from scipy.stats import mannwhitneyu\n    evs = {e["eid"]: e for e in (rjson(EV_REV, []) + rjson(EV_FIL, []))}\n    out = {}\n    labels = list(INTERVENTIONS)\n    if "steering" in labels and ROLL[("steering_llama8b_reextract", "revision")].exists():\n        for arm in ("revision", "filler"):\n            q = [r for r in (rjson(ROLL[("steering", arm)], []) or []) if r["model"] != LLAMA]\n            l8 = [r for r in (rjson(ROLL[("steering_llama8b_reextract", arm)], []) or []) if r["model"] == LLAMA]\n            wjson(q + l8, ROLL[("steering_corrected", arm)])\n        labels.insert(labels.index("steering"), "steering_corrected")\n    if "steering" in labels and ROLL[("steering_seed1000", "revision")].exists():\n        labels.append("steering_seed1000")\n    for label in labels:\n        iv = "steering" if label.startswith("steering") else label\n        note = {"steering_seed1000": "  (second seed set: 1000 + r; NOT the published procedure)",\n                "steering_corrected": "  (seeds 4000 + r; Llama-8B direction rebuilt from the re-extracted windows)"}\n        if label == "steering" and "steering_corrected" in labels:\n            note["steering"] = "  (seeds 4000 + r; Llama-8B direction from the ORIGINAL windows, superseded)"\n        hdr(f"{label.upper()}" + note.get(label, f"  (seeds {SEEDS[\'rollout_base\'][iv]} + r)"))\n        recs = {arm: rjson(ROLL[(label, arm)], []) or [] for arm in ("revision", "filler")}\n        fp_ = fingerprint(iv)\n        for arm in recs:\n            bad_ = sum(1 for r in recs[arm] if r.get("generator_fingerprint") != fp_)\n            if bad_:\n                print(f"  {arm}: {bad_} records NOT made by the production generator "\n                      f"-> excluded; re-run STAGE = \'{iv}\'")\n                recs[arm] = [r for r in recs[arm] if r.get("generator_fingerprint") == fp_]\n        if not recs["revision"] or not recs["filler"]:\n            print("  no rollouts yet"); continue\n\n        def score(rec, mode, drop_leaked=False):\n            g = gt.get((_short(rec["model"]), str(rec["problem_id"])))\n            texts = rec.get("rollout_texts") or []\n            if drop_leaked and rec.get("leaked"):\n                texts = [t for t, l in zip(texts, rec["leaked"]) if not l]\n            if g is None or not texts: return None\n            vals = []\n            for t in texts:\n                a = prod.extract_answer_new(t); unk = (a == "UNKNOWN")\n                if unk and mode == "dropped": continue\n                vals.append((mode == "as_correct") if unk else\n                            (prod.normalise_answer(a) == prod.normalise_answer(g)))\n            return None if not vals else 1.0 - sum(vals) / len(vals)\n\n        res = {}\n        variants = [("as_incorrect", False), ("dropped", False),\n                    ("as_correct", False)]\n        if iv == "lexical": variants.append(("as_incorrect", True))\n        for mode, dl in variants:\n            tag = mode + ("+leak_filter" if dl else "")\n            A = [(score(r, mode, dl), r) for r in recs["revision"]]\n            B = [(score(r, mode, dl), r) for r in recs["filler"]]\n            A = [(s, r) for s, r in A if s is not None]\n            B = [(s, r) for s, r in B if s is not None]\n            a = np.array([s for s, _ in A]); b = np.array([s for s, _ in B])\n            _, p = mannwhitneyu(a, b, alternative="two-sided")\n            lo1, hi1, G1 = boot_mean_diff(a, b, [str(r["problem_id"]) for _, r in A],\n                                          [str(r["problem_id"]) for _, r in B])\n            lo2, hi2, G2 = boot_mean_diff(a, b, [f"{r[\'model\']}|{r[\'problem_id\']}" for _, r in A],\n                                          [f"{r[\'model\']}|{r[\'problem_id\']}" for _, r in B])\n            res[tag] = {"n": f"{len(a)}/{len(b)}", "rev": float(a.mean()),\n                        "fil": float(b.mean()), "diff": float(a.mean() - b.mean()),\n                        "mw_p": float(p), "ci_problem": [lo1, hi1, G1],\n                        "ci_model_problem": [lo2, hi2, G2]}\n            print(f"  {tag:<26} n={len(a)}/{len(b)}  {a.mean():.4f} vs {b.mean():.4f}"\n                  f"  diff {a.mean()-b.mean():+.4f}  MW p={p:.4g}"\n                  f"  CI(problem, {G1}) [{lo1:+.4f}, {hi1:+.4f}]")\n            if mode == "as_incorrect" and not dl:\n                # repetition-controlled estimate, clustered by problem\n                rows = []\n                for s, r in A + B:\n                    e = evs.get(r.get("eid"))\n                    if e and e.get("repetition") is not None:\n                        rows.append((s, 1.0 if r["arm"] == "revision" else 0.0,\n                                     e["repetition"], str(r["problem_id"])))\n                if len(rows) > 20:\n                    Y = np.array([x[0] for x in rows]); X1 = np.array([x[1] for x in rows])\n                    C = np.array([x[2] for x in rows]); C = C - C.mean()\n                    beta, D, G = cluster_boot(Y, np.column_stack([np.ones_like(Y), X1, C]),\n                                              [x[3] for x in rows])\n                    lo, hi, pp = ci_p(D[:, 1])\n                    res["repetition_controlled"] = {"arm": float(beta[1]),\n                                                    "ci": [lo, hi], "p": pp,\n                                                    "rep_slope": float(beta[2]),\n                                                    "clusters": G}\n                    print(f"  {\'+ repetition (problem cl.)\':<26} arm {beta[1]:+.4f} "\n                          f"[{lo:+.4f}, {hi:+.4f}] p={pfmt(pp)}  slope {beta[2]:+.4f}")\n        # per model, and pooled without Llama-8B, NEW vs OLD rollouts scored\n        # by the same function (old files: published 83/80 rollouts)\n        OLD_FILES = {"lexical": ("counterfactual_rollout_results.json",\n                                 "filler_control_rollout_results.json"),\n                     "steering": ("steering_revision_rollouts_powered.json",\n                                  "steering_filler_rollouts_powered.json")}\n        oldr = {arm: rjson(EXPORT / f, []) or []\n                for arm, f in zip(("revision", "filler"), OLD_FILES[iv])}\n        def arm_means(rr, keep):\n            v = [score(r, "as_incorrect") for r in rr if keep(_short(r.get("model")))]\n            v = [x for x in v if x is not None]\n            return (float(np.mean(v)) if v else float("nan")), len(v)\n        print(f"\\n  per model, \'as_incorrect\' (NEW clean-prefix  |  OLD published)")\n        res["per_model"] = {}\n        groups_ = [(m, (lambda mm: (lambda x: x == mm))(m)) for m in MODELS]\n        if "DeepSeek-R1-Distill-Llama-8B" in MODELS and len(MODELS) > 1:\n            groups_.append(("pooled, excluding Llama-8B",\n                            lambda x: x != "DeepSeek-R1-Distill-Llama-8B"))\n        groups_.append(("pooled, these models", lambda x: x in MODELS))\n        for name, keep in groups_:\n            nr, nnr = arm_means(recs["revision"], keep)\n            nf, nnf = arm_means(recs["filler"], keep)\n            orr, onr = arm_means(oldr["revision"], keep)\n            of, onf = arm_means(oldr["filler"], keep)\n            print(f"    {name[-30:]:<31}NEW {nr:.3f} vs {nf:.3f} diff {nr-nf:+.3f}"\n                  f" (n {nnr}/{nnf})  |  OLD {orr:.3f} vs {of:.3f} diff {orr-of:+.3f}"\n                  f" (n {onr}/{onf})")\n            res["per_model"][name] = {"new": [nr, nf, nnr, nnf],\n                                      "old": [orr, of, onr, onf]}\n        # per model with CIs (appendix table): the pooled estimator applied to\n        # each model\'s events -- MW two-sided, cluster bootstrap by problem_id\n        # (B = N_BOOT, seed 8080, 2.5/97.5 percentiles)\n        print(f"\\n  per model, \'as_incorrect\', with CIs (NEW rollouts)")\n        res["per_model_ci"] = {}\n        for name in MODELS:\n            A = [(score(r, "as_incorrect"), r) for r in recs["revision"] if _short(r["model"]) == name]\n            B = [(score(r, "as_incorrect"), r) for r in recs["filler"] if _short(r["model"]) == name]\n            A = [(x, r) for x, r in A if x is not None]; B = [(x, r) for x, r in B if x is not None]\n            if len(A) < 2 or len(B) < 2:\n                continue\n            a = np.array([x for x, _ in A]); b = np.array([x for x, _ in B])\n            lo, hi, G = boot_mean_diff(a, b, [str(r["problem_id"]) for _, r in A],\n                                       [str(r["problem_id"]) for _, r in B])\n            _, p = mannwhitneyu(a, b, alternative="two-sided")\n            res["per_model_ci"][name] = {"n": f"{len(a)}/{len(b)}", "rev": float(a.mean()), "fil": float(b.mean()),\n                                         "diff": float(a.mean() - b.mean()), "mw_p": float(p),\n                                         "ci_problem": [lo, hi, G]}\n            print(f"    {name[-30:]:<31}{a.mean():.3f} vs {b.mean():.3f}  diff {a.mean()-b.mean():+.3f}"\n                  f"  MW p={p:.3g}  CI(problem, {G}) [{lo:+.3f}, {hi:+.3f}]  (n {len(a)}/{len(b)})")\n        # pooled-without-Llama CI, problem-clustered, as_incorrect\n        if "DeepSeek-R1-Distill-Llama-8B" in MODELS and len(MODELS) > 1:\n            A = [(score(r, "as_incorrect"), r) for r in recs["revision"]\n                 if _short(r["model"]) != "DeepSeek-R1-Distill-Llama-8B"]\n            B = [(score(r, "as_incorrect"), r) for r in recs["filler"]\n                 if _short(r["model"]) != "DeepSeek-R1-Distill-Llama-8B"]\n            A = [(x, r) for x, r in A if x is not None]; B = [(x, r) for x, r in B if x is not None]\n            a = np.array([x for x, _ in A]); b = np.array([x for x, _ in B])\n            lo, hi, G = boot_mean_diff(a, b, [str(r["problem_id"]) for _, r in A],\n                                       [str(r["problem_id"]) for _, r in B])\n            _, p = mannwhitneyu(a, b, alternative="two-sided")\n            print(f"    excluding Llama-8B: diff {a.mean()-b.mean():+.4f}  MW p={p:.4g}"\n                  f"  CI(problem, {G}) [{lo:+.4f}, {hi:+.4f}]")\n            res["excluding_llama8b"] = {"diff": float(a.mean() - b.mean()), "mw_p": float(p),\n                                        "ci_problem": [lo, hi, G]}\n        # equivalence with production necessity_scores on the same file\n        try:\n            pr = prod.necessity_scores(ROLL[(label, "revision")], gt,\n                                       prod.extract_answer_new, "as_incorrect")\n            mine = sorted(s for s in (score(r, "as_incorrect") for r in recs["revision"])\n                          if s is not None)\n            ok = len(pr) == len(mine) and np.allclose(\n                sorted(x["necessity"] for x in pr), mine)\n            print(f"  equivalence vs production necessity_scores(): "\n                  f"{\'OK\' if ok else \'MISMATCH\'} ({len(mine)} vs {len(pr)})")\n            res["equivalence_ok"] = bool(ok)\n        except Exception as e:\n            print(f"  equivalence check not run: {type(e).__name__}: {e}")\n        if iv == "lexical":\n            nl = sum(sum(r.get("leaked") or []) for r in recs["revision"] + recs["filler"])\n            nt = sum(len(r.get("rollout_texts") or []) for r in recs["revision"] + recs["filler"])\n            print(f"  leaked rollouts: {nl} of {nt}")\n            res["leaked"] = [nl, nt]\n        o = OLD[iv]\n        print(f"\\n  OLD ({o[\'n\']}): {o[\'rev\']:.3f} vs {o[\'fil\']:.3f}  diff +{o[\'diff\']:.3f}"\n              f"  p={o[\'p\']}  CI [{o[\'ci\'][0]:+.3f}, {o[\'ci\'][1]:+.3f}]"\n              f"  + repetition +{o[\'rep\']:.3f}")\n        out[label] = res\n\n    wjson(out, RESULTS)\n    manifest_add({"stage": "analyze", "started": datetime.fromtimestamp(t0, timezone.utc).isoformat(),\n                  "finished": now(), "wall_clock_s": round(time.time() - t0, 1),\n                  "env": env_info(), "sources": [src_scorer]})\n    print(f"\\n  wrote {RESULTS}")\n    if SAMPLE == "original":\n        print("""\n  ORIGINAL SAMPLE, CLEAN PREFIXES. Same 83/80 events as published; the only\n  changes are the restored prefix (Llama-8B), the two lexical events that were\n  never generated, and event-keyed resume. Qwen prefixes were already clean\n  and the seeds are the published ones (lexical 1000+r, steering 4000+r), so\n  for the three Qwen models NEW vs OLD is a replication check. Llama-8B NEW\n  vs OLD is the effect of the fix. STEERING_SEED1000 is the first steering\n  re-run, made with 1000+r by mistake: an independent seed set, not the\n  published procedure; a seed-robustness check only.""")\n    print("""\n  REPORT BOTH. The old 83/80 numbers stay as they were. \'as_incorrect\' without the leak filter\n  is the treatment the published necessity numbers used. The leak-filtered line is a sensitivity.""")\n\n\nif __name__ == "__main__" or True:\n    {"select": (stage_select_original if SAMPLE == "original" else stage_select),\n     "lexical": lambda: stage_generate("lexical"),\n     "steering": lambda: stage_generate("steering_llama8b_reextract" if LLAMA_DIRECTION == "reextract"\n                                        else "steering"),\n     "analyze": stage_analyze}[STAGE]()\n'

SRC['efficacy'] = '# =============================================================================\n# STEERING EFFICACY ON THE RE-RUN (clean prefixes)  +  RE-RUN COMPUTE TIME\n#\n# The paper\'s efficacy numbers (+19.3 / +31.0 / -2.0 / +50.5 %, "terms\n# reduction") came from steering_efficacy_report.json, written by the efficacy\n# diagnostic: an UNSTEERED (alpha = 0) baseline on the first 8 revision events\n# per model (sorted by problem_id), 2 rollouts each (seeds 9000 + r, 2048 new\n# tokens, temperature 0.6, top-p 0.95), compared with the steered rollouts on\n# the same events. Metric: mean number of distinct backtracking terms per\n# rollout (20 terms, observed, never banned), and\n#     terms_reduction_pct = (terms_base - terms_steer) / terms_base.\n#\n# That baseline was generated from the OLD prefixes, which for Llama-8B were in\n# byte-level characters. This file repeats the diagnostic on the re-run:\n#   STAGE = "baseline": regenerate the alpha = 0 baseline with the CLEAN\n#       prefixes, same subset rule, same seeds, same generation settings, same\n#       generation code (the diagnostic\'s loop, verbatim). GPU; 64 generations.\n#   STAGE = "report":  (CPU) recompute efficacy against the re-run\'s steered\n#       rollouts on the same events, and print beside it\n#         - the paper\'s values (old baseline vs old steered), and\n#         - the old baseline vs the NEW steered rollouts (a cross-check; for\n#           Llama-8B this mixes a corrupted-prefix baseline with clean-prefix\n#           steering and is labelled as such).\n#       Also sums the re-run\'s compute time from the per-event wall clocks\n#       stored in the rollout files and the per-session manifest records.\n#       If the Llama-8B steering re-run with the rebuilt direction exists\n#       (09, LLAMA_DIRECTION = "reextract"), its efficacy is reported too; that\n#       is the Llama-8B number the paper uses.\n#\n# Output: hand_labeling_export/redraw_2026_10/original_rerun_clean_prefix/\n#         steering_efficacy_baseline_clean.json, steering_efficacy_rerun.json\n# =============================================================================\nSTAGE = "baseline"        # baseline | report\n\nimport json, os, re, time\nfrom pathlib import Path\nfrom collections import defaultdict\n\nimport numpy as np\n\nBASE = Path(os.environ.get("REVISION_DATA_ROOT", "/content/gdrive/MyDrive/llm_planning_study"))\nif not BASE.exists():\n    from google.colab import drive; drive.mount("/content/gdrive")\nEXPORT  = BASE / "hand_labeling_export"\nRUN_DIR = EXPORT / "redraw_2026_10" / "original_rerun_clean_prefix"\nEV_REV        = RUN_DIR / "redraw_revision_events.json"\nSTEER_NEW     = RUN_DIR / "redraw_steering_revision_rollouts_seed4000.json"   # published seeds, 4000 + r\nSTEER_LLAMA_RE = RUN_DIR / "redraw_steering_revision_rollouts_seed4000_llama8b_reextract.json"  # Llama-8B, rebuilt direction\nROLL_FILES    = {("lexical", arm): RUN_DIR / f"redraw_lexical_{arm}_rollouts.json" for arm in ("revision", "filler")}\nROLL_FILES.update({("steering", arm): RUN_DIR / f"redraw_steering_{arm}_rollouts_seed4000.json"\n                   for arm in ("revision", "filler")})\nROLL_FILES.update({("steering_llama8b_reextract", arm):\n                   RUN_DIR / f"redraw_steering_{arm}_rollouts_seed4000_llama8b_reextract.json" for arm in ("revision", "filler")})\nROLL_FILES.update({("steering_seed1000", arm): RUN_DIR / f"redraw_steering_{arm}_rollouts.json"\n                   for arm in ("revision", "filler")})   # first steering re-run (1000 + r, not the procedure)\nMANIFEST      = RUN_DIR / "manifest.json"\nBASELINE_NEW  = RUN_DIR / "steering_efficacy_baseline_clean.json"\nREPORT_NEW    = RUN_DIR / "steering_efficacy_rerun.json"\nBASELINE_OLD  = EXPORT / "steering_efficacy_baseline.json"\nREPORT_OLD    = EXPORT / "steering_efficacy_report.json"\n\n# ---- from the efficacy diagnostic, verbatim ---------------------------------\nN_EVENTS_PER_MODEL     = 8\nN_ROLLOUTS             = 2\nROLLOUT_MAX_NEW_TOKENS = 2048\nSAMPLE_TEMPERATURE     = 0.6\nSAMPLE_TOP_P           = 0.95\nCHOSEN_ALPHA_MULTIPLIER = {\n    "DeepSeek-R1-Distill-Llama-8B":  1.5,\n    "DeepSeek-R1-Distill-Qwen-1.5B": 3.0,\n    "DeepSeek-R1-Distill-Qwen-7B":   1.5,\n    "DeepSeek-R1-Distill-Qwen-14B":  5.0,\n}\nBACKTRACK_TERMS = [\n    "wait", "actually", "alternatively", "hmm", "hold on",\n    "let me reconsider", "let me rethink", "on second thought",\n    "let me try again", "let me go back", "let me recheck",\n    "let me double check", "let me double-check",\n    "that\'s wrong", "that is wrong", "that\'s not right", "that is not right",\n    "i made a mistake", "i made an error", "this doesn\'t work",\n]\n\ndef extract_answer(text: str) -> str:\n    boxed = re.findall(r\'\\\\boxed\\{([^}]+)\\}\', text)\n    if boxed:\n        return boxed[-1].strip()\n    m = re.search(r\'(?:answer is|therefore)[:\\s]*([0-9A-Za-z\\-\\.\\/]+)\',\n                  text, re.IGNORECASE)\n    return m.group(1).strip() if m else "UNKNOWN"\n\ndef build_prompt(problem, tokenizer, model_name):\n    is_reasoning = any(t in model_name for t in ["R1", "QwQ"])\n    if problem.get("difficulty") == "hard":\n        instruction = ("Solve the following competition mathematics problem carefully. "\n                        "Show your reasoning step by step and verify your answer.")\n    else:\n        instruction = ("Solve the following mathematics competition problem. "\n                        "Show your working step by step.")\n    if is_reasoning:\n        msgs = [{"role": "user", "content": f"{instruction}\\n\\nProblem: {problem[\'problem\']}"}]\n    else:\n        msgs = [{"role": "system", "content": "You are an expert mathematician. Solve problems "\n                                              "with clear step-by-step reasoning."},\n                {"role": "user", "content": f"{instruction}\\n\\nProblem: {problem[\'problem\']}"}]\n    return tokenizer.apply_chat_template(msgs, tokenize=False, add_generation_prompt=True)\n\ndef backtrack_rate(texts):\n    if not texts:\n        return None\n    hits = sum(1 for t in texts if any(term in t.lower() for term in BACKTRACK_TERMS))\n    return hits / len(texts)\n\ndef terms_per_rollout(texts):\n    if not texts:\n        return None\n    return float(np.mean([sum(1 for term in BACKTRACK_TERMS if term in t.lower())\n                          for t in texts]))\n# -----------------------------------------------------------------------------\n\ndef rjson(p, d=None):\n    try: return json.load(open(p))\n    except Exception: return d\n\ndef wjson(o, p):\n    tmp = Path(str(p) + ".tmp"); json.dump(o, open(tmp, "w"), indent=2); os.replace(tmp, p)\n\ndef key(r): return (r["model"], str(r["problem_id"]), int(r["char_start"]))\n\ndef subset():\n    """The diagnostic\'s rule: first N revision events per model by problem_id\n    (stable sort, so ties keep event-file order)."""\n    by = defaultdict(list)\n    for e in rjson(EV_REV, []) or []:\n        by[e["model"]].append(e)\n    return {m: sorted(v, key=lambda e: e["problem_id"])[:N_EVENTS_PER_MODEL] for m, v in by.items()}\n\n\ndef stage_baseline():\n    import torch\n    from transformers import AutoTokenizer, AutoModelForCausalLM\n    out = rjson(BASELINE_NEW, []) or []\n    done = {key(r) for r in out}\n    if done:\n        print(f"Resuming: {len(done)} baseline events already done.")\n    for model_short, evs in subset().items():\n        remaining = [e for e in evs if key(e) not in done]\n        if not remaining:\n            print(f"\\n{model_short}: baseline complete -- skipping load."); continue\n        model_full = f"deepseek-ai/{model_short}"\n        print(f"\\n{\'=\'*62}\\n{model_full} — UNSTEERED baseline, clean prefixes ({len(remaining)} events)\\n{\'=\'*62}")\n        tok = AutoTokenizer.from_pretrained(model_full, trust_remote_code=True)\n        if tok.pad_token is None:\n            tok.pad_token = tok.eos_token\n        model = AutoModelForCausalLM.from_pretrained(\n            model_full, torch_dtype=torch.float16, device_map="auto", trust_remote_code=True)\n        model.eval()\n        for ev in remaining:\n            prompt = build_prompt({"problem": ev["problem"], "difficulty": ev["difficulty"]},\n                                  tok, model_full)\n            prefix = prompt + ev["prefix_response_text"]\n            texts = []\n            t0 = time.time()\n            for r in range(N_ROLLOUTS):\n                torch.manual_seed(9000 + r)\n                inp = tok(prefix, return_tensors="pt", truncation=False).to(model.device)\n                with torch.no_grad():\n                    o = model.generate(**inp, max_new_tokens=ROLLOUT_MAX_NEW_TOKENS,\n                                       do_sample=True, temperature=SAMPLE_TEMPERATURE,\n                                       top_p=SAMPLE_TOP_P, pad_token_id=tok.pad_token_id,\n                                       eos_token_id=tok.eos_token_id)\n                texts.append(tok.decode(o[0][inp["input_ids"].shape[1]:],\n                                        skip_special_tokens=False))\n            print(f"  {ev[\'eid\']} {ev[\'problem_id\']}: backtrack rate "\n                  f"{backtrack_rate(texts):.2f}  ({time.time()-t0:.0f}s)")\n            out.append({"eid": ev["eid"], "problem_id": ev["problem_id"], "model": model_short,\n                        "char_start": ev["char_start"], "alpha": 0.0,\n                        "seeds": [9000 + r for r in range(N_ROLLOUTS)],\n                        "wall_clock_s": round(time.time() - t0, 1), "rollout_texts": texts})\n            wjson(out, BASELINE_NEW)\n        del model\n        torch.cuda.empty_cache()\n    print(f"\\nWrote {len(out)} baseline events -> {BASELINE_NEW}")\n\n\ndef rows_for(base_by, steer_by):\n    rows = {}\n    for m in sorted(set(base_by) & set(steer_by)):\n        b, s = base_by[m], steer_by[m]\n        bt, st = terms_per_rollout(b), terms_per_rollout(s)\n        br, sr = backtrack_rate(b), backtrack_rate(s)\n        rows[m] = {"alpha_mult": CHOSEN_ALPHA_MULTIPLIER.get(m), "n_base": len(b), "n_steer": len(s),\n                   "backtrack_base": br, "backtrack_steer": sr, "backtrack_reduction": br - sr,\n                   "terms_base": bt, "terms_steer": st,\n                   "terms_reduction_pct": (bt - st) / bt if bt else None,\n                   "extract_base": float(np.mean([extract_answer(t) != "UNKNOWN" for t in b])),\n                   "extract_steer": float(np.mean([extract_answer(t) != "UNKNOWN" for t in s]))}\n    return rows\n\n\ndef stage_report():\n    sub = subset()\n    keys = {key(e) for v in sub.values() for e in v}\n    steer = [r for r in (rjson(STEER_NEW, []) or []) if key(r) in keys]\n    base = rjson(BASELINE_NEW, []) or []\n    s_by, b_by = defaultdict(list), defaultdict(list)\n    for r in steer: s_by[r["model"]].extend(r.get("rollout_texts") or [])\n    for r in base:  b_by[r["model"]].extend(r.get("rollout_texts") or [])\n    new = rows_for(b_by, s_by)\n    print(f"  inputs: clean-prefix baseline {len(base)} events "\n          f"({sum(float(r.get(\'wall_clock_s\') or 0) for r in base):.0f}s) in {BASELINE_NEW.name}; "\n          f"steered (4000 + r) {len(steer)} of {len(keys)} subset events in {STEER_NEW.name}"\n          + ("" if STEER_NEW.exists() else "  <- file not found: run 09 STAGE = \'steering\' first"))\n\n    # cross-check: the OLD baseline file against the NEW steered rollouts, on the\n    # events both cover (matched on model + problem_id, as the diagnostic did)\n    old_b = rjson(BASELINE_OLD, []) or []\n    ob_keys = {(r["model"], str(r["problem_id"])) for r in old_b}\n    s2 = defaultdict(list); ob = defaultdict(list)\n    for r in rjson(STEER_NEW, []) or []:\n        if (r["model"], str(r["problem_id"])) in ob_keys: s2[r["model"]].extend(r.get("rollout_texts") or [])\n    for r in old_b: ob[r["model"]].extend(r.get("rollout_texts") or [])\n    cross = rows_for(ob, s2)\n    paper = rjson(REPORT_OLD, {}) or {}\n\n    print(f"\\n{\'#\'*78}\\n# STEERING EFFICACY — terms reduction per model\\n{\'#\'*78}")\n    print(f"  {\'model\':<16}{\'k\':>5}  {\'paper (old/old)\':>16}  {\'re-run (new/new)\':>17}  "\n          f"{\'old base/new steer\':>19}  {\'extract base->steer (new)\':>26}")\n    for m in sorted(set(new) | set(paper) | set(cross)):\n        f = lambda d: (f"{d[m][\'terms_reduction_pct\']:+.1%}" if m in d and d[m].get("terms_reduction_pct") is not None else "n/a")\n        ex = (f"{new[m][\'extract_base\']:.0%} -> {new[m][\'extract_steer\']:.0%}" if m in new else "")\n        flag = "  (old baseline had byte-level prefixes)" if "Llama-8B" in m else ""\n        print(f"  {m[-15:]:<16}{CHOSEN_ALPHA_MULTIPLIER.get(m, \'\'):>5}  {f(paper):>16}  {f(new):>17}  "\n              f"{f(cross):>19}  {ex:>26}{flag}")\n    for m, r in new.items():\n        print(f"    {m[-15:]}: terms/rollout {r[\'terms_base\']:.2f} -> {r[\'terms_steer\']:.2f}  "\n              f"(n rollouts {r[\'n_base\']} base / {r[\'n_steer\']} steered)")\n    llama_re = {}\n    if STEER_LLAMA_RE.exists():\n        s3 = defaultdict(list)\n        for r in rjson(STEER_LLAMA_RE, []) or []:\n            if key(r) in keys and "Llama-8B" in r["model"]:\n                s3[r["model"]].extend(r.get("rollout_texts") or [])\n        llama_re = rows_for(b_by, s3)\n        for m, r in llama_re.items():\n            print(f"\\n  {m}, direction REBUILT from the re-extracted windows (k = {r[\'alpha_mult\']}):")\n            print(f"    terms reduction {r[\'terms_reduction_pct\']:+.1%}  (terms/rollout {r[\'terms_base\']:.2f} -> "\n                  f"{r[\'terms_steer\']:.2f}; n {r[\'n_base\']} base / {r[\'n_steer\']} steered)  "\n                  f"extract {r[\'extract_base\']:.0%} -> {r[\'extract_steer\']:.0%}")\n            if m in new:\n                print(f"    (original-window direction: {new[m][\'terms_reduction_pct\']:+.1%})")\n\n    # ---- compute time --------------------------------------------------------\n    timing = {}\n    for (iv, arm), p in ROLL_FILES.items():\n        for r in rjson(p, []) or []:\n            t = timing.setdefault(iv, {"events": 0, "sum_event_wall_clock_s": 0.0, "by_model": defaultdict(float),\n                                       "gpus": set()})\n            t["events"] += 1; t["sum_event_wall_clock_s"] += float(r.get("wall_clock_s") or 0)\n            t["by_model"][r["model"]] += float(r.get("wall_clock_s") or 0); t["gpus"].add(r.get("gpu"))\n    sessions = defaultdict(list)\n    for rec in ((rjson(MANIFEST, {}) or {}).get("stages") or []):\n        if isinstance(rec, dict) and rec.get("stage") in ("lexical", "steering", "steering_llama8b_reextract"):\n            rb = (rec.get("seeds") or {}).get("rollout_base")\n            lab = rec["stage"]\n            if lab == "steering" and not isinstance(rb, dict):     # first re-run: one base (1000) for both\n                lab = "steering_seed1000"\n            sessions[lab].append({"started": rec.get("started"), "finished": rec.get("finished"),\n                                           "wall_clock_s": rec.get("wall_clock_s"),\n                                           "per_model_wall_clock_s": rec.get("per_model_wall_clock_s")})\n    for iv, t in timing.items():\n        t["by_model"] = dict(t["by_model"]); t["gpus"] = sorted(g for g in t["gpus"] if g)\n        t["sessions"] = sessions.get(iv, [])\n        t["sum_session_wall_clock_s"] = float(sum(s["wall_clock_s"] or 0 for s in t["sessions"]))\n        print(f"\\n  {iv}: {t[\'events\']} events; sum of per-event wall clock {t[\'sum_event_wall_clock_s\']:.0f}s "\n              f"({t[\'sum_event_wall_clock_s\']/3600:.1f} h); {len(t[\'sessions\'])} session(s) in the manifest, "\n              f"total {t[\'sum_session_wall_clock_s\']:.0f}s (includes model loading); GPU {t[\'gpus\']}")\n        for m, s in sorted(t["by_model"].items()):\n            print(f"      {m[-15:]:<16}{s:>9.0f}s")\n    base_s = sum(float(r.get("wall_clock_s") or 0) for r in base)\n    out = {"subset_rule": f"first {N_EVENTS_PER_MODEL} revision events per model by problem_id",\n           "subset": {m: [e["eid"] for e in v] for m, v in sub.items()},\n           "rerun_new_baseline_vs_new_steered": new,\n           "llama8b_rebuilt_direction": llama_re,\n           "old_baseline_vs_new_steered": cross,\n           "paper_old_baseline_vs_old_steered": paper,\n           "compute": timing, "efficacy_baseline_wall_clock_s": base_s}\n    wjson(out, REPORT_NEW)\n    print(f"\\nWrote {REPORT_NEW}")\n\n\nif STAGE == "baseline":\n    stage_baseline()\nelif STAGE == "report":\n    stage_report()\nelse:\n    raise SystemExit(f"unknown STAGE {STAGE!r}")\n'


def patched(src, pairs):
    for pat, rep in pairs:
        src, n = re.subn(pat, rep, src, count=1, flags=re.M)
        if n != 1:
            raise RuntimeError(f"settings line not found: {pat}")
    return src

STEPS = [
    ("1. direction", "reextract", [(r'^STAGES = \[.*$', 'STAGES = ["direction"]')],
     lambda: (EXPORT / "steering_directions_llama8b_reextract.json").exists()),
    ("2. steering (Llama-8B, rebuilt direction)", "necessity",
     [(r'^STAGE\s*=\s*"[a-z]+"', 'STAGE = "steering"'), (r'^LLAMA_DIRECTION = "[a-z]+"', 'LLAMA_DIRECTION = "reextract"'),
      (r'^SAMPLE\s*=\s*"[a-z]+"', 'SAMPLE = "original"')], None),
    ("3. analyze", "necessity",
     [(r'^STAGE\s*=\s*"[a-z]+"', 'STAGE = "analyze"'), (r'^SAMPLE\s*=\s*"[a-z]+"', 'SAMPLE = "original"')], None),
    ("4. steering efficacy report", "efficacy", [(r'^STAGE = "[a-z]+"', 'STAGE = "report"')], None),
]

with contextlib.redirect_stdout(Tee(sys.stdout)):
    print(f"\n{'#'*78}\n# RUN ALL started {time.strftime('%Y-%m-%d %H:%M:%S')}\n{'#'*78}")
    for name, key, pairs, done in STEPS:
        print(f"\n{'#'*78}\n# {name}\n{'#'*78}", flush=True)
        if done is not None and done():
            print("  already done (output file exists); skipped"); continue
        t0 = time.time()
        try:
            exec(compile(patched(SRC[key], pairs), f"<{key}>", "exec"), {"__name__": "__main__"})
        except SystemExit as e:
            if e.code not in (None, 0):
                print(f"\n  STOPPED in {name}: {e.code}\n  Later steps were not run. Fix this, then run the file again.")
                break
        except Exception:
            traceback.print_exc(file=sys.stdout)
            print(f"\n  FAILED in {name}. Later steps were not run. Run the file again to resume.")
            break
        print(f"\n  {name}: finished in {time.time() - t0:.0f}s", flush=True)
    else:
        print(f"\n{'#'*78}\n# ALL STEPS DONE {time.strftime('%Y-%m-%d %H:%M:%S')}\n"
              f"# results: redraw_results.json (STEERING_CORRECTED), steering_efficacy_rerun.json\n"
              f"# log: {LOG}\n{'#'*78}")
